window.AUTH=window.AUTH||{};window.AUTH["17-1042"]={"d":"17-1042","id":"2018/17-1042","n":"BNSF Railway Co. v. Loos","briefs":[{"k":"petitioner","label":"Brief of petitioner BNSF Railway Company","date":"2018-07-20","url":"https://www.supremecourt.gov/DocketPDF/17/17-1042/54944/20180720142857087_281505_Brief-Addendum.pdf","side":"pet","n":89},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2018-07-27","url":"https://www.supremecourt.gov/DocketPDF/17/17-1042/55824/20180727193509947_17-1042tsacUnitedStates.pdf","side":"us","n":57},{"k":"respondent","label":"Brief of respondent Michael Loos","date":"2018-09-10","url":"https://www.supremecourt.gov/DocketPDF/17/17-1042/63216/20180910174832238_17-1042bs.pdf","side":"res","n":86},{"k":"reply","label":"Reply of petitioner BNSF Railway Company","date":"2018-10-10","url":"https://www.supremecourt.gov/DocketPDF/17/17-1042/66480/20181010170653117_17-1042rb%2010-10-18.pdf","side":"pet","n":28}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1042_new_7648.pdf","tr":true,"items":[{"t":"case","label":"A. Brod, Inc. v. SK & I Co.","cite":"998 F. Supp. 314","y":1998,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./998/314/","by":{"0":"29"}},{"t":"case","label":"Alton Railroad Co. v. R.R. Retirement Bd.","cite":"16 F. Supp. 955","y":1936,"court":"D. D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./16/955/","by":{"0":"5","1":"3","2":"3"}},{"t":"case","label":"Am. Bank & Trust Co. v. Dallas Cnty.","cite":"463 U.S. 855","y":1983,"id":"1982/81-1717","sc":1,"sum":"1.The Texas tax on bank shares violates Rev. Stat. §3701, as amended.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Architectronics, Inc. v. Control Sys.","cite":"935 F. Supp. 425","y":1996,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./935/425/","by":{"0":"29"}},{"t":"case","label":"Atchison, Topeka & Santa Fe Ry. v. United States","cite":"628 F. Supp. 1431","y":1986,"court":"D. Kan.","url":"https://www.courtlistener.com/c/F.%20Supp./628/1431/","sum":"Stating that, “[a]fter the 1946 amendments, it was unclear whether compensation was to be taxed on an ‘as earned’ or an ‘as paid’ basis,” and noting the railroad’s contention “that the IRS routinely taxed on an ‘as earned’ basis”.","sumSrc":"brief:1","by":{"0":"33","1":"6"}},{"t":"case","label":"Atl. Land & Improvement Co. v. United States","cite":"790 F.2d 853","y":1986,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/790/853/","by":{"0":"25","1":"21"}},{"t":"case","label":"Carland Inc. v. United States","cite":"1995 WL 218576","y":1995,"court":"W.D. Mo. Feb. 14","by":{"0":"26"}},{"t":"case","label":"Cheetham v. CSX Transp., No 06-cv-704","cite":"2012 WL 1424168","y":2012,"court":"M.D. Fla. Feb. 13","by":{"0":"22"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. Natural Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"13, 36","1":"11, 15, 16","2":"15, 52, 54"}},{"t":"case","label":"Chi. Milwaukee Corp. v. United States","cite":"35 Fed. Cl. 447","y":1996,"url":"https://www.courtlistener.com/c/Fed.%20Cl./35/447/","by":{"0":"33"}},{"t":"case","label":"Cowden v. BNSF Ry. Co.","cite":"2014 WL 3096867","y":2014,"court":"E.D. Mo. July 7","by":{"0":"22, 45"}},{"t":"case","label":"Davis v. United States","cite":"495 U.S. 472","y":1990,"id":"1989/89-98","sc":1,"sum":"Section 170 of the Internal Revenue Code of 1954 permits a taxpayer to claim a charitable contribution deduction only if the contribution is made \"to or for the use of\" a qualified organization. Petitioner husband and wife, who are members of the Church of Jesus Christ of Latter-day Saints (Church) claimed such deductions for funds transferred to their sons while they were serving as full-time, unpaid missionaries …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"sum":"The Court held that 18 U.S.C. Section 924(c)(1)(A)(iii) does not require proof of intent to discharge a firearm in order to enhance a sentence.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Eichel v. New York Cent. R. Co.","cite":"375 U.S. 253","y":1963,"id":"1963/480","sc":1,"sum":"The District Court properly excluded the evidence of disability payments. Pp. 253-256. 319 F. 2d 12, reversed and remanded. Arnold B. Elkind and Richard C. Machcinski for petitioner. Gerald E. Dwyer for respondent.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3"}},{"t":"case","label":"Elgin v. Dep’t of Treasury","cite":"567 U.S. 1","y":2012,"id":"2011/11-45","sc":1,"sum":"The Court held that the Civil Service Reform Act precludes federal courts' jurisdiction in cases where federal employees seek equitable relief.","sumSrc":"Oyez","by":{"0":"42","2":"51"}},{"t":"case","label":"Erlenbaugh v. United States","cite":"409 U.S. 239","y":1972,"id":"1972/71-839","sc":1,"sum":"Causing a publication to be carried by a facility of interstate commerce with an intent to facilitate the operation of an illegal gambling business is a violation of 18 U. S. C. § 1952. The exception for \"any newspaper or similar publication\" contained in 18 U. S. C. § 1953, which prohibits the interstate shipment of certain gambling paraphernalia, was not intended to be read into § 1952. Pp. 242-248. 452 F. 2d 967, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","1":"21","2":"32"}},{"t":"case","label":"Federal Land Bank of St. Paul v. Bismarck Lumber Co.","cite":"314 U.S. 95","y":1941,"id":"scdb/1941-013","sc":1,"by":{"0":"23","1":"22","2":"27"}},{"t":"case","label":"Good Samaritan Hosp. v. Shalala","cite":"508 U.S. 402","y":1993,"id":"1992/91-2079","sc":1,"sum":"Title 42 U. S. C. § 1395f(b)(1) requires the Secretary of Health and Human Services to reimburse the lesser of the \"customary charges\" or the \"reasonable cost[s]\" of providers of health care services to Medicare beneficiaries, while § 1395x(v)(1)(A) empowers the Secretary to issue regulations setting forth the methods to be used in computing reasonable costs, which may include the establishment of appropriate cost …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Hance v. Norfolk S. Ry. Co.","cite":"571 F.3d 511","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/571/511/","op":1,"by":{"0":"22"}},{"t":"case","label":"Heckman v. Burlington N. Santa Fe Ry.","cite":"837 N.W.2d 532","y":2013,"court":"Neb.","url":"https://www.courtlistener.com/c/N.W.2d/837/532/","op":1,"by":{"0":"22"}},{"t":"case","label":"Hisquierdo v. Hisquierdo","cite":"439 U.S. 572","y":1979,"id":"1978/77-533","sc":1,"op":2,"ar":2,"sum":"Benefits payable under the Act may not be divided under the community property law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 3","2":"4, 30, 46"}},{"t":"case","label":"Liberatore v. Monongahela Ry. Co.","cite":"140 A.3d 16","y":2016,"court":"Pa. Super. Ct.","url":"https://www.courtlistener.com/c/A.3d/140/16/","by":{"0":"22, 25, 27, 47","3":"15"}},{"t":"case","label":"Livingston Rebuild Center v. R.R. Retirement Board","cite":"970 F.2d 295","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/970/295/","by":{"0":"26"}},{"t":"case","label":"Mayo Found. v. United States","cite":"562 U.S. 44","y":2011,"id":"2010/09-837","sc":1,"sum":"A case in which the Court upheld the Treasury Department's rule that treats medical residents as full-time employees, and therefore not exempt from the payment of payroll taxes.","sumSrc":"Oyez","by":{"0":"36","1":"15, 33"}},{"t":"case","label":"Mickey v. BNSF Ry Co.","cite":"437 S.W.3d 207","y":2014,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.3d/437/207/","op":1,"sum":"Noting that the RRTA’s broad definition of “compensation” does not specifically mention pay for time lost.","sumSrc":"brief:0","by":{"0":"22, 38"}},{"t":"case","label":"Missouri Pac. Truck Lines, Inc. v. United States","cite":"3 Cl. Ct. 14","y":1983,"url":"https://www.courtlistener.com/c/Cl.%20Ct./3/14/","by":{"0":"26"}},{"t":"case","label":"Nielsen v. BNSF Ry. Co.","cite":"2012 WL 12526344","y":2012,"court":"Oregon Cir. Ct. Mar. 5","sum":"Noting that the RRTA’s broad definition of “compensation” does not specifically mention pay for time lost.","sumSrc":"brief:0","by":{"0":"22","2":"55"}},{"t":"case","label":"NLRB v. Bell Aerospace Co.","cite":"416 U.S. 267","y":1974,"id":"1973/72-1598","sc":1,"sum":"On a petition by a labor union for a representation election, the National Labor Relations Board (NLRB) held that the buyers employed by respondent company constituted an appropriate collective-bargaining unit and directed an election. The NLRB stated that even though the buyers might be \"managerial employees\" they were nevprtheless covered by the National Labor Relations Act (NLRA) in the absence of any showing …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36","3":"24"}},{"t":"case","label":"Norfolk S. Ry. Co. v. Williams","cite":"2018 WL 2995699","y":2018,"court":"Ala. App. June 15","by":{"0":"passim"}},{"t":"case","label":"Norwegian Nitrogen Products Co. v. United States","cite":"288 U.S. 294","y":1933,"id":"scdb/1932-150","sc":1,"sum":"The Tariff Act of 1922 empowers the President to change rates of duty in order to equalize differences in costs of production in this country and abroad, but provides--§ 315 (c)-that before he acts there shall have been an investigation of such differences by the Tariff Commission, in the making of which the Commission shall give reasonable public notice of its hearings, and shall give \"reasonable opportunity to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"P.C. Pfeiffer Co. v. Ford","cite":"444 U.S. 69","y":1979,"id":"1978/78-425","sc":1,"sum":"Ford and Bryant were engaged in maritime employment at the time of their injuries because they were engaged in intermediate steps of moving cargo between ship and land transportation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","2":"26"}},{"t":"case","label":"Phillips v. Chicago Cent. & Pacific R.R.","cite":"853 N.W.2d 636","y":2014,"court":"Iowa.","url":"https://www.courtlistener.com/c/N.W.2d/853/636/","op":1,"by":{"0":"22, 25, 33","3":"10, 11, 12"}},{"t":"case","label":"Railroad Retirement Board v. Alton Railroad Company","cite":"295 U.S. 330","y":1935,"id":"scdb/1934-051","sc":1,"sum":"1. The power of Congress to regulate interstate commerce is subject to the guaranty of due process in the Fifth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5","2":"2"}},{"t":"case","label":"Shattuck v. Gallagher","cite":"218 F.3d 428","y":1955,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/218/428/","by":{"0":"24"}},{"t":"case","label":"Soc. Sec. Bd. v. Nierotko","cite":"327 U.S. 358","y":1946,"id":"scdb/1945-109","sc":1,"op":25,"ar":12,"sum":"Finding that back pay for time in which an employee was not working due to unlawful discharge constituted payment arising from “the entire employer-employee relationship”.","sumSrc":"brief:1","by":{"0":"13, 14, 19, 20","1":"13, 16, 17, 18, 19, 23","2":"34, 35, 36, 37, 39, 34, 35","3":"5, 12, 16"}},{"t":"case","label":"Standard Office Bldg. Corp. v. United States","cite":"819 F.2d 1371","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/819/1371/","by":{"0":"1"}},{"t":"case","label":"United Savings Ass’n of Texas v. Timbers of Inwood Forest Associates","cite":"484 U.S. 365","y":1988,"id":"1987/86-1602","sc":1,"sum":"Undersecured creditors are not entitled to compensation under § 362(d)(1) for the delay caused by the automatic stay in foreclosing on their collateral.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","2":"31"}},{"t":"case","label":"United States v. Bean","cite":"537 U.S. 71","y":2002,"id":"2002/01-704","sc":1,"sum":"The Court held that the absence of an actual denial of Bean's petition by ATF precludes judicial review.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"United States v. Bess","cite":"357 U.S. 51","y":1958,"id":"1957/395","sc":1,"sum":"Because of thetax liens which had attached to all of the insured's property before his death, the beneficiary is liable to the extent of the cash surrender values of his policies.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","2":"51"}},{"t":"case","label":"United States v. Correll","cite":"389 U.S. 299","y":1967,"id":"1967/113","sc":1,"sum":"The Commissioner of Internal Revenue's long-standing ruling that \"traveling expenses\" incurred in the pursuit of business \"while away from home,\" which are deductible under § 162 (a) (2) of the Internal Revenue Code of 1954, include the cost of meals only if the trip requires sleep or rest, held to achieve not only ease and certainty of application but also substantial fairness and to be within the Commissioner's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 34"}},{"t":"case","label":"United States v. Gonzalez","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"United States v. Quality Stores, Inc.","cite":"134 S. Ct. 1395","y":2014,"id":"2013/12-1408","sc":1,"op":10,"ar":3,"sum":"The Court found that severance payments made to employees who were unwillingly laid off are taxable under the Federal Insurance Contributions Act.","sumSrc":"Oyez","by":{"0":"13, 14, 20, 22","1":"13, 18, 19","2":"27, 34, 37, 39","3":"4, 5, 6, 8"}},{"t":"case","label":"Universal Carloading & Distrib. Co. v. Pedrick","cite":"184 F.2d 64","y":1950,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/184/64/","by":{"0":"25","1":"21","3":"11"}},{"t":"case","label":"Vodden v. BNSF Ry. Co.","cite":"2012 WL 7150849","y":2012,"court":"Minn. Dist. Ct. Dec. 19","by":{"0":"22"}},{"t":"usc","label":"26 U.S.C. § 61","url":"https://www.law.cornell.edu/uscode/text/26/61","stext":{"head":"§61. Gross income defined","paras":[[0,"(a) General definition"],[0,"Except as otherwise provided in this subtitle, gross income means all income from whatever source derived, including (but not limited to) the following items:"],[1,"(1) Compensation for services, including fees, commissions, fringe benefits, and similar items;"],[1,"(2) Gross income derived from business;"],[1,"(3) Gains derived from dealings in property;"],[1,"(4) Interest;"],[1,"(5) Rents;"],[1,"(6) Royalties;"],[1,"(7) Dividends;"],[1,"(8) Annuities;"],[1,"(9) Income from life insurance and endowment contracts;"],[1,"(10) Pensions;"],[1,"(11) Income from discharge of indebtedness;"],[1,"(12) Distributive share of partnership gross income;"],[1,"(13) Income in respect of a decedent; and"],[1,"(14) Income from an interest in an estate or trust."],[0,"(b) Cross references"],[2,"For items specifically included in gross income, see part II (sec. 71 and following). For items specifically excluded from gross income, see part III (sec. 101 and following)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/61?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§61. Gross income defined","tname":"Internal Revenue Code","by":{"0":"38","3":"20"}},{"t":"usc","label":"26 U.S.C. § 63","url":"https://www.law.cornell.edu/uscode/text/26/63","subs":["(a)"],"by":{"0":"38"}},{"t":"usc","label":"26 U.S.C. § 104","url":"https://www.law.cornell.edu/uscode/text/26/104","subs":["(a)(2)"],"stext":{"head":"§104. Compensation for injuries or sickness","paras":[[0,"(a) In general"],[0,"Except in the case of amounts attributable to (and not in excess of) deductions allowed under section 213 (relating to medical, etc., expenses) for any prior taxable year, gross income does not include—"],[1,"(1) amounts received under workmen's compensation acts as compensation for personal injuries or sickness;"],[1,"(2) the amount of any damages (other than punitive damages) received (whether by suit or agreement and whether as lump sums or as periodic payments) on account of personal physical injuries or physical sickness;"],[1,"(3) amounts received through accident or health insurance (or through an arrangement having the effect of accident or health insurance) for personal injuries or sickness (other than amounts received by an employee, to the extent such amounts (A) are attributable to contributions by the employer which were not includible in the gross income of the employee, or (B) are paid by the employer);"],[1,"(4) amounts received as a pension, annuity, or similar allowance for personal injuries or sickness resulting from active service in the armed forces of any country or in the Coast and Geodetic Survey or the Public Health Service, or as a disability annuity payable under the provisions of section 808 of the Foreign Service Act of 1980;"],[1,"(5) amounts received by an individual as disability income attributable to injuries incurred as a direct result of a terroristic or military action (as defined in section 692(c)(2)); and"],[1,"(6) amounts received pursuant to—"],[2,"(A) section 1201 of the Omnibus Crime Control and Safe Streets Act of 1968 (42 U.S.C. 3796); 1 or"],[2,"(B) a program established under the laws of any State which provides monetary compensation for surviving dependents of a public safety officer who has died as the direct and proximate result of a personal injury sustained in the line of duty,"],[1,"except that subparagraph (B) shall not apply to any amounts that would have been payable if death of the public safety officer had occurred other than as the direct and proximate result of a personal injury sustained in the line of duty."],[0,"For purposes of paragraph (3), in the case of an individual who is, or has been, an employee within the meaning of section 401(c)(1) (relating to self-employed individuals), contributions made on behalf of such individual while he was such an employee to a trust described in section 401(a) which is exempt from tax under section 501(a), or under a plan described in section 403(a), shall, to the extent allowed as deductions under section 404, be treated as contributions by the employer which were not includible in the gross income of the employee. For purposes of paragraph (2), emotional distress shall not be treated as a physical injury or physical sickness. The preceding sentence shall not apply to an amount of damages not in excess of the amount paid for medical care (described in subparagraph (A) or (B) of section 213(d)(1)) attributable to emotional distress."],[0,"(b) Termination of application of subsection (a)(4) in certain cases"],[0,"(1) In general"],[1,"Subsection (a)(4) shall not apply in the case of any individual who is not described in paragraph (2)."],[0,"(2) Individuals to whom subsection (a)(4) continues to apply"],[1,"An individual is described in this paragraph if—"],[2,"(A) on or before September 24, 1975, he was entitled to receive any amount described in subsection (a)(4),"],[2,"(B) on September 24, 1975, he was a member of any organization (or reserve component thereof) referred to in subsection (a)(4) or under a binding written commitment to become such a member,"],[2,"(C) he receives an amount described in subsection (a)(4) by reason of a combat-related injury, or"],[2,"(D) on application therefor, he would be entitled to receive disability compensation from the Department of Veterans Affairs."],[0,"(3) Special rules for combat-related injuries"],[1,"For purposes of this subsection, the term \"combat-related injury\" means personal injury or sickness—"],[2,"(A) which is incurred—"],[3,"(i) as a direct result of armed conflict,"],[3,"(ii) while engaged in extrahazardous service, or"],[3,"(iii) under conditions simulating war; or"],[2,"(B) which is caused by an instrumentality of war."],[1,"In the case of an individual who is not described in subparagraph (A) or (B) of paragraph (2), except as provided in paragraph (4), the only amounts taken into account under subsection (a)(4) shall be the amounts which he receives by reason of a combat-related injury."],[0,"(4) Amount excluded to be not less than veterans' disability compensation"],[1,"In the case of any individual described in paragraph (2), the amounts excludable under subsection (a)(4) for any period with respect to any individual shall not be less than the maximum amount which such individual, on application therefor, would be entitled to receive as disability compensation from the Veterans' Administration."],[0,"(c) Application of prior law in certain cases"],[0,"The phrase \"(other than punitive damages)\" shall not apply to punitive damages awarded in a civil action—"],[1,"(1) which is a wrongful death action, and"],[1,"(2) with respect to which applicable State law (as in effect on September 13, 1995 and without regard to any modification after such date) provides, or has been construed to provide by a court of competent jurisdiction pursuant to a decision issued on or before September 13, 1995, that only punitive damages may be awarded in such an action."],[0,"This subsection shall cease to apply to any civil action filed on or after the first date on which the applicable State law ceases to provide (or is no longer construed to provide) the treatment described in paragraph (2)."],[0,"(d) Cross references"],[2,"(1) For exclusion from employee's gross income of employer contributions to accident and health plans, see section 106."],[2,"(2) For exclusion of part of disability retirement pay from the application of subsection (a)(4) of this section, see section 1403 of title 10, United States Code (relating to career compensation laws)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/104?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§104. Compensation for injuries or sickness","tname":"Internal Revenue Code","by":{"0":"passim, 16, 38, 44, 45"}},{"t":"usc","label":"26 U.S.C. § 1532","url":"https://www.law.cornell.edu/uscode/text/26/1532","subs":["(e)"],"by":{"0":"6, 7, 39"}},{"t":"usc","label":"26 U.S.C. § 3121","url":"https://www.law.cornell.edu/uscode/text/26/3121","subs":["(b)","(a)","(b)(9)"],"stext":{"head":"§3121. Definitions","paras":[[0,"(a) Wages"],[0,"For purposes of this chapter, the term \"wages\" means all remuneration for employment, including the cash value of all remuneration (including benefits) paid in any medium other than cash; except that such term shall not include—"],[1,"(1) in the case of the taxes imposed by sections 3101(a) and 3111(a) that part of the remuneration which, after remuneration (other than remuneration referred to in the succeeding paragraphs of this subsection) equal to the contribution and benefit base (as determined under section 230 of the Social Security Act) with respect to employment has been paid to an individual by an employer during the calendar year with respect to which such contribution and benefit base is effective, is paid to such individual by such employer during such calendar year. If an employer (hereinafter referred to as successor employer) during any calendar year acquires substantially all the property used in a trade or business of another employer (hereinafter referred to as a predecessor), or used in a separate unit of a trade or business of a predecessor, and immediately after the acquisition employs in his trade or business an individual who immediately prior to the acquisition was employed in the trade or business of such predecessor, then, for the purpose of determining whether the successor employer has paid remuneration (other than remuneration referred to in the succeeding paragraphs of this subsection) with respect to employment equal to the contribution and benefit base (as determined under section 230 of the Social Security Act) to such individual during such calendar year, any remuneration (other than remuneration referred to in the succeeding paragraphs of this subsection) with respect to employment paid (or considered under this paragraph as having been paid) to such individual by such predecessor during such calendar year and prior to such acquisition shall be considered as having been paid by such successor employer;"],[1,"(2) the amount of any payment (including any amount paid by an employer for insurance or annuities, or into a fund, to provide for any such payment) made to, or on behalf of, an employee or any of his dependents under a plan or system established by an employer which makes provision for his employees generally (or for his employees generally and their dependents) or for a class or classes of his employees (or for a class or classes of his employees and their dependents), on account of—"],[2,"(A) sickness or accident disability (but, in the case of payments made to an employee or any of his dependents, this subparagraph shall exclude from the term \"wages\" only payments which are received under a workman's compensation law), or"],[2,"(B) medical or hospitalization expenses in connection with sickness or accident disability, or"],[2,"(C) death, except that this paragraph does not apply to a payment for group-term life insurance to the extent that such payment is includible in the gross income of the employee;"],[1,"[(3) Repealed. Pub. L. 98–21, title III, §324(a)(3)(B), Apr. 20, 1983, 97 Stat. 123]"],[1,"(4) any payment on account of sickness or accident disability, or medical or hospitalization expenses in connection with sickness or accident disability, made by an employer to, or on behalf of, an employee after the expiration of 6 calendar months following the last calendar month in which the employee worked for such employer;"],[1,"(5) any payment made to, or on behalf of, an employee or his beneficiary—"],[2,"(A) from or to a trust described in section 401(a) which is exempt from tax under section 501(a) at the time of such payment unless such payment is made to an employee of the trust as remuneration for services rendered as such employee and not as a beneficiary of the trust,"],[2,"(B) under or to an annuity plan which, at the time of such payment, is a plan described in section 403(a),"],[2,"(C) under a simplified employee pension (as defined in section 408(k)(1)), other than any contributions described in section 408(k)(6),"],[2,"(D) under or to an annuity contract described in section 403(b), other than a payment for the purchase of such contract which is made by reason of a salary reduction agreement (whether evidenced by a written instrument or otherwise),"],[2,"(E) under or to an exempt governmental deferred compensation plan (as defined in subsection (v)(3)),"],[2,"(F) to supplement pension benefits under a plan or trust described in any of the foregoing provisions of this paragraph to take into account some portion or all of the increase in the cost of living (as determined by the Secretary of Labor) since retirement but only if such supplemental payments are under a plan which is treated as a welfare plan under section 3(2)(B)(ii) of the Employee Retirement Income Security Act of 1974,"],[2,"(G) under a cafeteria plan (within the meaning of section 125) if such payment would not be treated as wages without regard to such plan and it is reasonable to believe that (if section 125 applied for purposes of this section) section 125 would not treat any wages as constructively received,"],[2,"(H) under an arrangement to which section 408(p) applies, other than any elective contributions under paragraph (2)(A)(i) thereof, or"],[2,"(I) under a plan described in section 457(e)(11)(A)(ii) and maintained by an eligible employer (as defined in section 457(e)(1));"],[1,"(6) the payment by an employer (without deduction from the remuneration of the employee)—"],[2,"(A) of the tax imposed upon an employee under section 3101, or"],[2,"(B) of any payment required from an employee under a State unemployment compensation law,"],[1,"with respect to remuneration paid to an employee for domestic service in a private home of the employer or for agricultural labor;"],[1,"(7)(A) remuneration paid in any medium other than cash to an employee for service not in the course of the employer's trade or business or for domestic service in a private home of the employer;"],[1,"(B) cash remuneration paid by an employer in any calendar year to an employee for domestic service in a private home of the employer (including domestic service on a farm operated for profit), if the cash remuneration paid in such year by the employer to the employee for such service is less than the applicable dollar threshold (as defined in subsection (x)) for such year;"],[1,"(C) cash remuneration paid by an employer in any calendar year to an employee for service not in the course of the employer's trade or business, if the cash remuneration paid in such year by the employer to the employee for such service is less than $100. As used in this subparagraph, the term \"service not in the course of the employer's trade or business\" does not include domestic service in a private home of the employer and does not include service described in subsection (g)(5);"],[1,"(8)(A) remuneration paid in any medium other than cash for agricultural labor;"],[1,"(B) cash remuneration paid by an employer in any calendar year to an employee for agricultural labor unless—"],[2,"(i) the cash remuneration paid in such year by the employer to the employee for such labor is $150 or more, or"],[2,"(ii) the employer's expenditures for agricultural labor in such year equal or exceed $2,500,"],[1,"except that clause (ii) shall not apply in determining whether remuneration paid to an employee constitutes \"wages\" under this section if such employee (I) is employed as a hand harvest laborer and is paid on a piece rate basis in an operation which has been, and is customarily and generally recognized as having been, paid on a piece rate basis in the region of employment, (II) commutes daily from his permanent residence to the farm on which he is so employed, and (III) has been employed in agriculture less than 13 weeks during the preceding calendar year;"],[1,"[(9) Repealed. Pub. L. 98–21, title III, §324(a)(3)(B), Apr. 20, 1983, 97 Stat. 123]"],[1,"(10) remuneration paid by an employer in any calendar year to an employee for service described in subsection (d)(3)(C) (relating to home workers), if the cash remuneration paid in such year by the employer to the employee for such service is less than $100;"],[1,"(11) remuneration paid to or on behalf of an employee if (and to the extent that) at the time of the payment of such remuneration it is reasonable to believe that a corresponding deduction is allowable under section 217 (determined without regard to section 274(n));"],[1,"(12)(A) tips paid in any medium other than cash;"],[1,"(B) cash tips received by an employee in any calendar month in the course of his employment by an employer unless the amount of such cash tips is $20 or more;"],[1,"(13) any payment or series of payments by an employer to an employee or any of his dependents which is paid—"],[2,"(A) upon or after the termination of an employee's employment relationship because of (i) death, or (ii) retirement for disability, and"],[2,"(B) under a plan established by the employer which makes provision for his employees generally or a class or classes of his employees (or for such employees or class or classes of employees and their dependents),"],[1,"other than any such payment or series of payments which would have been paid if the employee's employment relationship had not been so terminated;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3121?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§3121. Definitions","tname":"Internal Revenue Code","by":{"0":"20","1":"19, 19, 2"}},{"t":"usc","label":"26 U.S.C. § 3201","url":"https://www.law.cornell.edu/uscode/text/26/3201","subs":["(a)"],"stext":{"head":"§3201. Rate of tax","paras":[[0,"(a) Tier 1 tax"],[0,"In addition to other taxes, there is hereby imposed on the income of each employee a tax equal to the applicable percentage of the compensation received during any calendar year by such employee for services rendered by such employee. For purposes of the preceding sentence, the term \"applicable percentage\" means the percentage equal to the sum of the rates of tax in effect under subsections (a) and (b) of section 3101 for the calendar year."],[0,"(b) Tier 2 tax"],[0,"In addition to other taxes, there is hereby imposed on the income of each employee a tax equal to the percentage determined under section 3241 for any calendar year of the compensation received during such calendar year by such employee for services rendered by such employee."],[0,"(c) Cross reference"],[2,"For application of different contribution bases with respect to the taxes imposed by subsections (a) and (b), see section 3231(e)(2)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3201?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§3201. Rate of tax","tname":"Internal Revenue Code","by":{"0":"3, 39, 5","1":"1","2":"passim"}},{"t":"usc","label":"26 U.S.C. § 3202","url":"https://www.law.cornell.edu/uscode/text/26/3202","subs":["(a)"],"by":{"0":"4"}},{"t":"usc","label":"26 U.S.C. § 3221","url":"https://www.law.cornell.edu/uscode/text/26/3221","subs":["(a)"],"stext":{"head":"§3221. Rate of tax","paras":[[0,"(a) Tier 1 tax"],[0,"In addition to other taxes, there is hereby imposed on every employer an excise tax, with respect to having individuals in his employ, equal to the applicable percentage of compensation paid during any calendar year by such employer for services rendered to such employer. For purposes of the preceding sentence, the term \"applicable percentage\" means the percentage equal to the sum of the rates of tax in effect under subsections (a) and (b) of section 3111 for the calendar year."],[0,"(b) Tier 2 tax"],[0,"In addition to other taxes, there is hereby imposed on every employer an excise tax, with respect to having individuals in his employ, equal to the percentage determined under section 3241 for any calendar year of the compensation paid during such calendar year by such employer for services rendered to such employer."],[0,"(c) Cross reference"],[2,"For application of different contribution bases with respect to the taxes imposed by subsections (a) and (b), see section 3231(e)(2)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3221?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§3221. Rate of tax","tname":"Internal Revenue Code","by":{"0":"4, 5"}},{"t":"usc","label":"26 U.S.C. § 3231","url":"https://www.law.cornell.edu/uscode/text/26/3231","subs":["(e)","(e)(1)","(e)(1)(i)(1976)","(e)(2)(1981)","(e)(4)(A)","(e)(5)","(e)(1)(1970)","(e)(1)(1976)","(e)(2)(1976)","(e)(2)(1982)","(e)(2)","(e)(4)(B)","(e)(4)(C)"],"stext":{"head":"§3231. Definitions","paras":[[0,"(a) Employer"],[0,"For purposes of this chapter, the term \"employer\" means any carrier (as defined in subsection (g)), and any company which is directly or indirectly owned or controlled by one or more such carriers or under common control therewith, and which operates any equipment or facility or performs any service (except trucking service, casual service, and the casual operation of equipment or facilities) in connection with the transportation of passengers or property by railroad, or the receipt, delivery, elevation, transfer in transit, refrigeration or icing, storage, or handling of property transported by railroad, and any receiver, trustee, or other individual or body, judicial or otherwise, when in the possession of the property or operating all or any part of the business of any such employer; except that the term \"employer\" shall not include any street, interurban, or suburban electric railway, unless such railway is operating as a part of a general steam-railroad system of transportation, but shall not exclude any part of the general steam-railroad system of transportation now or hereafter operated by any other motive power. The Surface Transportation Board is hereby authorized and directed upon request of the Secretary, or upon complaint of any party interested, to determine after hearing whether any line operated by electric power falls within the terms of this exception. The term \"employer\" shall also include railroad associations, traffic associations, tariff bureaus, demurrage bureaus, weighing and inspection bureaus, collection agencies and other associations, bureaus, agencies, or organizations controlled and maintained wholly or principally by two or more employers as hereinbefore defined and engaged in the performance of services in connection with or incidental to railroad transportation; and railway labor organizations, national in scope, which have been or may be organized in accordance with the provisions of the Railway Labor Act, as amended (45 U.S.C., chapter 8), and their State and National legislative committees and their general committees and their insurance departments and their local lodges and divisions, established pursuant to the constitutions and bylaws of such organizations. The term \"employer\" shall not include any company by reason of its being engaged in the mining of coal, the supplying of coal to an employer where delivery is not beyond the mine tipple, and the operation of equipment or facilities therefor, or in any of such activities."],[0,"(b) Employee"],[0,"For purposes of this chapter, the term \"employee\" means any individual in the service of one or more employers for compensation. The term \"employee\" includes an officer of an employer. The term \"employee\" shall not include any individual while such individual is engaged in the physical operations consisting of the mining of coal, the preparation of coal, the handling (other than movement by rail with standard railroad locomotives) of coal not beyond the mine tipple, or the loading of coal at the tipple."],[0,"(c) Employee representative"],[0,"For purposes of this chapter, the term \"employee representative\" means any officer or official representative of a railway labor organization other than a labor organization included in the term \"employer\" as defined in subsection (a), who before or after June 29, 1937, was in the service of an employer as defined in subsection (a) and who is duly authorized and designated to represent employees in accordance with the Railway Labor Act (45 U.S.C., chapter 8), as amended, and any individual who is regularly assigned to or regularly employed by such officer or official representative in connection with the duties of his office."],[0,"(d) Service"],[0,"For purposes of this chapter, an individual is in the service of an employer whether his service is rendered within or without the United States, if—"],[1,"(1) he is subject to the continuing authority of the employer to supervise and direct the manner of rendition of his service, or he is rendering professional or technical services and is integrated into the staff of the employer, or he is rendering, on the property used in the employer's operations, other personal services the rendition of which is integrated into the employer's operations, and"],[1,"(2) he renders such service for compensation;"],[0,"except that an individual shall be deemed to be in the service of an employer, other than a local lodge or division or a general committee of a railway-labor-organization employer, not conducting the principal part of its business in the United States, only when he is rendering service to it in the United States; and an individual shall be deemed to be in the service of such a local lodge or division only if—"],[1,"(3) all, or substantially all, the individuals constituting its membership are employees of an employer conducting the principal part of its business in the United States; or"],[1,"(4) the headquarters of such local lodge or division is located in the United States;"],[0,"and an individual shall be deemed to be in the service of such a general committee only if—"],[1,"(5) he is representing a local lodge or division described in paragraph (3) or (4) immediately above; or"],[1,"(6) all, or substantially all, the individuals represented by it are employees of an employer conducting the principal part of its business in the United States; or"],[1,"(7) he acts in the capacity of a general chairman or an assistant general chairman of a general committee which represents individuals rendering service in the United States to an employer, but in such case if his office or headquarters is not located in the United States and the individuals represented by such general committee are employees of an employer not conducting the principal part of its business in the United States, only such proportion of the remuneration for such service shall be regarded as compensation as the proportion which the mileage in the United States under the jurisdiction of such general committee bears to the total mileage under its jurisdiction, unless such mileage formula is inapplicable, in which case such other formula as the Railroad Retirement Board may have prescribed pursuant to section 1(c) of the Railroad Retirement Act of 1937 (45 U.S.C. 228a) shall be applicable, and if the application of such mileage formula, or such other formula as the Board may prescribe, would result in the compensation of the individual being less than 10 percent of his remuneration for such service, no part of such remuneration shall be regarded as compensation;"],[0,"Provided however, That an individual not a citizen or resident of the United States shall not be deemed to be in the service of an employer when rendering service outside the United States to an employer who is required under the laws applicable in the place where the service is rendered to employ therein, in whole or in part, citizens or residents thereof; and the laws applicable on August 29, 1935, in the place where the service is rendered shall be deemed to have been applicable there at all times prior to that date."],[0,"(e) Compensation"],[0,"For purposes of this chapter—"],[1,"(1) The term \"compensation\" means any form of money remuneration paid to an individual for services rendered as an employee to one or more employers. Such term does not include (i) the amount of any payment (including any amount paid by an employer for insurance or annuities, or into a fund, to provide for any such payment) made to, or on behalf of, an employee or any of his dependents under a plan or system established by an employer which makes provision for his employees generally (or for his employees generally and their dependents) or for a class or classes of his employees (or for a class or classes of his employees and their dependents), on account of sickness or accident disability or medical or hospitalization expenses in connection with sickness or accident disability or death, except that this clause does not apply to a payment for group-term life insurance to the extent that such payment is includible in the gross income of the employee, (ii) tips (except as is provided under paragraph (3)), (iii) an amount paid specifically—either as an advance, as reimbursement or allowance—for traveling or other bona fide and necessary expenses incurred or reasonably expected to be incurred in the business of the employer provided any such payment is identified by the employer either by a separate payment or by specifically indicating the separate amounts where both wages and expense reimbursement or allowance are combined in a single payment, or (iv) any remuneration which would not (if chapter 21 applied to such remuneration) be treated as wages (as defined in section 3121(a)) by reason of section 3121(a)(5). Such term does not include remuneration for service which is performed by a nonresident alien individual for the period he is temporarily present in the United States as a nonimmigrant under subparagraph (F), (J), (M), or (Q) of section 101(a)(15) of the Immigration and Nationality Act, as amended, and which is performed to carry out the purpose specified in subparagraph (F), (J), (M), or (Q), as the case may be. For the purpose of determining the amount of taxes under sections 3201 and 3221, compensation earned in the service of a local lodge or division of a railway-labor-organization employer shall be disregarded with respect to any calendar month if the amount thereof is less than $25. Compensation for service as a delegate to a national or international convention of a railway labor organization defined as an \"employer\" in subsection (a) of this section shall be disregarded for purposes of determining the amount of taxes due pursuant to this chapter if the individual rendering such service has not previously rendered service, other than as such a delegate, which may be included in his \"years of service\" for purposes of the Railroad Retirement Act. Nothing in the regulations prescribed for purposes of chapter 24 (relating to wage withholding) which provides an exclusion from \"wages\" as used in such chapter shall be construed to require a similar exclusion from \"compensation\" in regulations prescribed for purposes of this chapter."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3231?type=usc&year=mostrecent&link-type=html"},"op":9,"head":"§3231. Definitions","tname":"Internal Revenue Code","by":{"0":"passim, 23, 8, 21, 8, 22, 41, 46","1":"27, 7, 7, 28, 28, 9, 29, 20, 20, 20, 20"}},{"t":"usc","label":"26 U.S.C. § 7501","url":"https://www.law.cornell.edu/uscode/text/26/7501","by":{"0":"4"}},{"t":"usc","label":"26 U.S.C. § 7801","url":"https://www.law.cornell.edu/uscode/text/26/7801","by":{"0":"4"}},{"t":"usc","label":"26 U.S.C. § 7805","url":"https://www.law.cornell.edu/uscode/text/26/7805","by":{"0":"4, 9, 34"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","by":{"0":"2"}},{"t":"usc","label":"42 U.S.C. § 410","url":"https://www.law.cornell.edu/uscode/text/42/410","subs":["(a)(9)"],"stext":{"head":"§410. Definitions relating to employment","paras":[[0,"For the purposes of this subchapter—"],[0,"(a) Employment"],[0,"The term \"employment\" means any service performed after 1936 and prior to 1951 which was employment for the purposes of this subchapter under the law applicable to the period in which such service was performed, and any service, of whatever nature, performed after 1950 (A) by an employee for the person employing him, irrespective of the citizenship or residence of either, (i) within the United States, or (ii) on or in connection with an American vessel or American aircraft under a contract of service which is entered into within the United States or during the performance of which and while the employee is employed on the vessel or aircraft it touches at a port in the United States, if the employee is employed on and in connection with such vessel or aircraft when outside the United States, or (B) outside the United States by a citizen or resident of the United States as an employee (i) of an American employer (as defined in subsection (e) of this section), or (ii) of a foreign affiliate (as defined in section 3121(l)(6) of the Internal Revenue Code of 1986) of an American employer during any period for which there is in effect an agreement, entered into pursuant to section 3121(l) of such Code, with respect to such affiliate, or (C) if it is service, regardless of where or by whom performed, which is designated as employment or recognized as equivalent to employment under an agreement entered into under section 433 of this title; except that, in the case of service performed after 1950, such term shall not include—"],[1,"(1) Service performed by foreign agricultural workers lawfully admitted to the United States from the Bahamas, Jamaica, and the other British West Indies, or from any other foreign country or possession thereof, on a temporary basis to perform agricultural labor;"],[1,"(2) Domestic service performed in a local college club, or local chapter of a college fraternity or sorority, by a student who is enrolled and is regularly attending classes at a school, college, or university;"],[1,"(3)(A) Service performed by a child under the age of 18 in the employ of his father or mother;"],[1,"(B) Service not in the course of the employer's trade or business, or domestic service in a private home of the employer, performed by an individual under the age of 21 in the employ of his father or mother, or performed by an individual in the employ of his spouse or son or daughter; except that the provisions of this subparagraph shall not be applicable to such domestic service performed by an individual in the employ of his son or daughter if—"],[2,"(i) the employer is a surviving spouse or a divorced individual and has not remarried, or has a spouse living in the home who has a mental or physical condition which results in such spouse's being incapable of caring for a son, daughter, stepson, or stepdaughter (referred to in clause (ii)) for at least 4 continuous weeks in the calendar quarter in which the service is rendered, and"],[2,"(ii) a son, daughter, stepson, or stepdaughter of such employer is living in the home, and"],[2,"(iii) the son, daughter, stepson, or stepdaughter (referred to in clause (ii)) has not attained age 18 or has a mental or physical condition which requires the personal care and supervision of an adult for at least 4 continuous weeks in the calendar quarter in which the service is rendered;"],[1,"(4) Service performed by an individual on or in connection with a vessel not an American vessel, or on or in connection with an aircraft not an American aircraft, if (A) the individual is employed on and in connection with such vessel or aircraft when outside the United States and (B)(i) such individual is not a citizen of the United States or (ii) the employer is not an American employer;"],[1,"(5) Service performed in the employ of the United States or any instrumentality of the United States, if such service—"],[2,"(A) would be excluded from the term \"employment\" for purposes of this subchapter if the provisions of paragraphs (5) and (6) of this subsection as in effect in January 1983 had remained in effect, and"],[2,"(B) is performed by an individual who—"],[3,"(i) has been continuously performing service described in subparagraph (A) since December 31, 1983, and for purposes of this clause—"],[4,"(I) if an individual performing service described in subparagraph (A) returns to the performance of such service after being separated therefrom for a period of less than 366 consecutive days, regardless of whether the period began before, on, or after December 31, 1983, then such service shall be considered continuous,"],[4,"(II) if an individual performing service described in subparagraph (A) returns to the performance of such service after being detailed or transferred to an international organization as described under section 3343 of subchapter III of chapter 33 of title 5 or under section 3581 of chapter 35 of such title, then the service performed for that organization shall be considered service described in subparagraph (A),"],[4,"(III) if an individual performing service described in subparagraph (A) is reemployed or reinstated after being separated from such service for the purpose of accepting employment with the American Institute of Taiwan as provided under section 3310 of title 22, then the service performed for that Institute shall be considered service described in subparagraph (A),"],[4,"(IV) if an individual performing service described in subparagraph (A) returns to the performance of such service after performing service as a member of a uniformed service (including, for purposes of this clause, service in the National Guard and temporary service in the Coast Guard Reserve) and after exercising restoration or reemployment rights as provided under chapter 43 of title 38, then the service so performed as a member of a uniformed service shall be considered service described in subparagraph (A), and"],[4,"(V) if an individual performing service described in subparagraph (A) returns to the performance of such service after employment (by a tribal organization) to which section 5323(e)(2) of title 25 applies, then the service performed for that tribal organization shall be considered service described in subparagraph (A); or"],[3,"(ii) is receiving an annuity from the Civil Service Retirement and Disability Fund, or benefits (for service as an employee) under another retirement system established by a law of the United States for employees of the Federal Government (other than for members of the uniformed services);"],[1,"except that this paragraph shall not apply with respect to any such service performed on or after any date on which such individual performs—"],[2,"(C) service performed as the President or Vice President of the United States,"],[2,"(D) service performed—"],[3,"(i) in a position placed in the Executive Schedule under sections 5312 through 5317 of title 5,"],[3,"(ii) as a noncareer appointee in the Senior Executive Service or a noncareer member of the Senior Foreign Service, or"],[3,"(iii) in a position to which the individual is appointed by the President (or his designee) or the Vice President under section 105(a)(1), 106(a)(1), or 107(a)(1) or (b)(1) of title 3, if the maximum rate of basic pay for such position is at or above the rate for level V of the Executive Schedule,"],[2,"(E) service performed as the Chief Justice of the United States, an Associate Justice of the Supreme Court, a judge of a United States court of appeals, a judge of a United States district court (including the district court of a territory), a judge of the United States Court of Federal Claims, a judge of the United States Court of International Trade, a judge or special trial judge of the United States Tax Court, a United States magistrate judge, or a referee in bankruptcy or United States bankruptcy judge,"],[2,"(F) service performed as a Member, Delegate, or Resident Commissioner of or to the Congress,"],[2,"(G) any other service in the legislative branch of the Federal Government if such service—"],[3,"(i) is performed by an individual who was not subject to subchapter III of chapter 83 of title 5 or to another retirement system established by a law of the United States for employees of the Federal Government (other than for members of the uniformed services), on December 31, 1983, or"],[3,"(ii) is performed by an individual who has, at any time after December 31, 1983, received a lump-sum payment under section 8342(a) of title 5 or under the corresponding provision of the law establishing the other retirement system described in clause (i), or"],[3,"(iii) is performed by an individual after such individual has otherwise ceased to be subject to subchapter III of chapter 83 of title 5, (without having an application pending for coverage under such subchapter), while performing service in the legislative branch (determined without regard to the provisions of subparagraph (B) relating to continuity of employment), for any period of time after December 31, 1983,"],[2,"and for purposes of this subparagraph (G) an individual is subject to such subchapter III or to any such other retirement system at any time only if (a) such individual's pay is subject to deductions, contributions, or similar payments (concurrent with the service being performed at that time) under section 8334(a) of such title 5 or the corresponding provision of the law establishing such other system, or (in a case to which section 8332(k)(1) of such title applies) such individual is making payments of amounts equivalent to such deductions, contributions, or similar payments while on leave without pay, or (b) such individual is receiving an annuity from the Civil Service Retirement and Disability Fund, or is receiving benefits (for service as an employee) under another retirement system established by a law of the United States for employees of the Federal Government (other than for members of the uniformed services), or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/410?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§410. Definitions relating to employment","tname":"The Public Health and Welfare","by":{"0":"2"}},{"t":"usc","label":"45 U.S.C. § 231","url":"https://www.law.cornell.edu/uscode/text/45/231","subs":["(h)","(h)(1)","(h)(2)","(o)"],"stext":{"head":"§231. Definitions","paras":[[0,"For the purposes of this subchapter—"],[0,"(a)(1) The term \"employer\" shall include—"],[1,"(i) any carrier by railroad subject to the jurisdiction of the Surface Transportation Board under part A of subtitle IV of title 49;"],[1,"(ii) any company which is directly or indirectly owned or controlled by, or under common control with, one or more employers as defined in paragraph (i) of this subdivision, and which operates any equipment or facility or performs any service (except trucking service, casual service, and the casual operation of equipment or facilities) in connection with the transportation of passengers or property by railroad, or the receipt, delivery, elevation, transfer in transit, refrigeration or icing, storage, or handling of property transported by railroad;"],[1,"(iii) any receiver, trustee, or other individual or body, judicial or otherwise, when in the possession of the property or operating all or any part of the business of any employer as defined in paragraph (i) or (ii) of this subdivision;"],[1,"(iv) any railroad association, traffic association, tariff bureau, demurrage bureau, weighing and inspection bureau, collection agency and any other association, bureau, agency, or organization which is controlled and maintained wholly or principally by two or more employers as defined in paragraph (i), (ii), or (iii) of this subdivision and which is engaged in the performance of services in connection with or incidental to railroad transportation; and"],[1,"(v) any railway labor organization, national in scope, which has been or may be organized in accordance with the provisions of the Railway Labor Act, as amended [45 U.S.C. 151 et seq.], and its State and National legislative committees, general committees, insurance departments, and local lodges and divisions, established pursuant to the constitution or bylaws of such organization."],[0,"(2) Notwithstanding the provisions of subdivision (1) of this subsection, the term \"employer\" shall not include—"],[1,"(i) any company by reason of its being engaged in the mining of coal, the supplying of coal to an employer where delivery is not beyond the mine tipple, and the operation of equipment or facilities therefor, or in any of such activities, and"],[1,"(ii) any street, interurban, or suburban electric railway, unless such railway is operating as a part of a general diesel-railroad system of transportation, but shall not exclude any part of the general diesel-railroad system of transportation now or hereafter operated by any other motive power. The Surface Transportation Board is hereby authorized and directed upon request of the Railroad Retirement Board, or upon complaint of any party interested, to determine after hearing whether any line operated by electric power falls within the terms of this paragraph."],[0,"(b)(1) The term \"employee\" means (i) any individual in the service of one or more employers for compensation, (ii) any individual who is in the employment relation to one or more employers, and (iii) an employee representative: Provided, however, That the term \"employee\" shall include an employee of a local lodge or division defined as an employer in subsection (a) only if he was in the service of or in the employment relation to an employer as defined in paragraph (i) of subsection (a)(1) on or after August 29, 1935."],[0,"(2) The term \"employee\" shall not include any individual while such individual is engaged in the physical operations consisting of the mining of coal, the preparation of coal, the handling (other than movement by rail with standard railroad locomotives) of coal not beyond the mine tipple, or the loading of coal at the tipple."],[0,"(c) The term \"employee representative\" means any officer or official representative of a railway labor organization other than a labor organization included in the term \"employer\" as defined in subsection (a) who before or after August 29, 1935, was in the service of an employer as defined in subsection (a) and who is duly authorized and designated to represent employees in accordance with the Railway Labor Act, as amended [45 U.S.C. 151 et seq.], and any individual who is regularly assigned to or regularly employed by such officer or official representative in connection with the duties of his office."],[0,"(d)(1) An individual is in the service of an employer whether his service is rendered within or without the United States if—"],[1,"(i)(A) he is subject to the continuing authority of the employer to supervise and direct the manner of rendition of his service, or (B) he is rendering professional or technical services and is integrated into the staff of the employer, or (C) he is rendering, on the property used in the employer's operations, personal services the rendition of which is integrated into the employer's operations; and"],[1,"(ii) he renders such service for compensation, or a method of computing the monthly compensation for such service is provided in section 231b(j) of this title."],[0,"(2) Notwithstanding the provisions of subdivision (1) of this subsection—"],[1,"(i) an individual shall be deemed to be in the service of an employer, other than a local lodge or division or a general committee of a railway-labor-organization employer, not conducting the principal part of its business in the United States only when he is rendering service to it in the United States;"],[1,"(ii) an individual shall be deemed to be in the service of a local lodge or division of a railway-labor-organization employer not conducting the principal part of its business in the United States only if (A) all, or substantially all, the individuals constituting the membership of such local lodge or division are employees of an employer conducting the principal part of its business in the United States; or (B) the headquarters of such local lodge or division is located in the United States; and"],[1,"(iii) an individual shall be deemed to be in the service of a general committee of a railway-labor-organization employer not conducting the principal part of its business in the United States only if (A) he is representing a local lodge or division described in clause (A) or (B) of paragraph (ii); or (B) all, or substantially all, the individuals represented by such general committee are employees of an employer conducting the principal part of its business in the United States; or (C) he acts in the capacity of a general chairman or an assistant general chairman of a general committee which represents individuals rendering service in the United States to an employer, but in such case if his office or headquarters is not located in the United States and the individuals represented by such general committee are employees of an employer not conducting the principal part of its business in the United States only such proportion of the remuneration for such service shall be regarded as compensation as the proportion which the mileage in the United States under the jurisdiction of such general committee bears to the total mileage under its jurisdiction, unless such mileage formula is inapplicable, in which case the Board may prescribe such other formula as it finds to be equitable, and if the application of such mileage formula, or such other formula as the Board may prescribe, would result in the compensation of the individual being less than 10 per centum of his remuneration for such service no part of such remuneration shall be regarded as compensation."],[0,"(3) Notwithstanding the provisions of subdivisions (1) and (2) of this subsection, an individual not a citizen or resident of the United States shall not be deemed to be in the service of an employer when rendering service outside the United States to an employer who is required under the laws applicable in the place where the service is rendered to employ therein, in whole or in part, citizens or residents thereof. For purposes of this subdivision, the laws applicable on August 29, 1935, in the place where the service is rendered shall be deemed to have been applicable there at all times prior to that date."],[0,"(e)(1) An individual shall be deemed to have been in the employment relation to an employer on August 29, 1935, if—"],[1,"(i) he was on that date on leave of absence from his employment, expressly granted to him by the employer by whom he was employed, or by a duly authorized representative of such employer, and the grant of such leave of absence will have been established to the satisfaction of the Board before July 1947;"],[1,"(ii) he was in the service of an employer after August 29, 1935, and before January 1946 in each of six calendar months, whether or not consecutive;"],[1,"(iii) before August 29, 1935, he did not retire and was not retired or discharged from the service of the last employer by whom he was employed or its corporate or operating successor, but (A) solely by reason of his physical or mental disability he ceased before August 29, 1935, to be in the service of such employer and thereafter remained continuously disabled until he attained age sixty-five or until August 1945, or (B) solely for such last stated reason an employer by whom he was employed before August 29, 1935, or an employer who is its successor did not on or after August 29, 1935, and before August 1945 call him to return to service, or (C) if he was so called he was solely for such reason unable to render service in six calendar months as provided in paragraph (ii); or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/231?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§231. Definitions","tname":"Railroads","by":{"0":"6, 7, 9, 23, 27, 9, 24","1":"1, 33, 33, 2"}},{"t":"usc","label":"45 U.S.C. § 231a","url":"https://www.law.cornell.edu/uscode/text/45/231a","subs":["(a)(1)","(b)"],"stext":{"head":"§231a. Annuity eligibility requirements","paras":[[0,"(a) Individuals eligible for annuities; disability standards; proof of continued disability"],[0,"(1) The following-described individuals, if they shall have completed ten years of service (or, for purposes of paragraphs (i), (iii), and (v), five years of service, all of which accrues after December 31, 1995) and shall have filed application for annuities, shall, subject to the conditions set forth in subsections (e), (f), and (h), be entitled to annuities in the amounts provided under section 231b of this title—"],[1,"(i) individuals who have attained retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]);"],[1,"(ii) individuals who have attained the age of sixty and have completed thirty years of service;"],[1,"(iii) individuals who have attained the age of sixty-two and have completed less than thirty years of service, but the annuity of such individuals shall be reduced by 1/180 for each of the first 36 months that he or she is under retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]) when the annuity begins to accrue and by 1/240 for each additional month that he or she is under retirement age (as defined in section 216(l) of the Social Security Act) when the annuity begins to accrue;"],[1,"(iv) individuals who have a current connection with the railroad industry, whose permanent physical or mental condition is such as to be disabling for work in their regular occupation, and who (A) have completed twenty years of service or (B) have attained the age of sixty; and"],[1,"(v) individuals whose permanent physical or mental condition is such that they are unable to engage in any regular employment."],[0,"(2) For the purposes of paragraph (iv) of subdivision (1), the Board, with the cooperation of employers and employees, shall secure the establishment of standards determining the physical and mental conditions which permanently disqualify employees for work in the several occupations in the railroad industry, and the Board, employers, and employees shall cooperate in the promotion of the greatest practicable degree of uniformity in the standards applied by the several employers. An individual's condition shall be deemed to be disabling for work in his regular occupation if he will have been disqualified by his employer for service in his regular occupation in accordance with the applicable standards so established; if the employee will not have been so disqualified by his employer, the Board shall determine whether his condition is disabling for work in his regular occupation in accordance with the standards generally established; and, if the employee's regular occupation is not one with respect to which standards will have been established, the standards relating to a reasonably comparable occupation shall be used. If there is no such comparable occupation, the Board shall determine whether the employee's condition is disabling for work in his regular occupation by determining whether under the practices generally prevailing in industries in which such occupation exists such condition is a permanent disqualification for work in such occupation. For purposes of this subdivision and paragraph (iv) of subdivision (1), an employee's \"regular occupation\" shall be deemed to be the occupation in which he will have been engaged in more calendar months than the calendar months in which he will have been engaged in any other occupation during the last preceding five calendar years, whether or not consecutive, in each of which years he will have earned wages or salary, except that, if an employee establishes that during the last fifteen consecutive calendar years he will have been engaged in another occupation in one-half or more of all the months in which he will have earned wages or salary, he may claim such other occupation as his regular occupation."],[0,"(3) Such satisfactory proof shall be made from time to time as prescribed by the Board, of the disability provided for in paragraph (iv) or (v) of subdivision (1) and of the continuance of such disability (according to the standards applied in the establishment of such disability) until the employee attains retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]). If the individual fails to comply with the requirements prescribed by the Board as to proof of the continuance of the disability until he attains retirement age (as defined in section 216(l) of the Social Security Act), his right to an annuity by reason of such disability shall, except for good cause shown to the Board, cease, but without prejudice to his rights to any subsequent annuity to which he may be entitled."],[0,"(4) An individual who is entitled to an annuity under paragraph (v) of subdivision (1), but who does not have at least ten years of service, shall, prior to the month in which the individual attains age 62, be entitled only to an annuity amount computed under section 231b(a) of this title (without regard to section 231b(a)(2) of this title) or section 231b(f)(3) of this title. Upon attainment of age 62, such an individual may also be entitled to an annuity amount computed under section 231b(b) of this title, but such annuity amount shall be reduced for early retirement in the same manner as if the individual were entitled to an annuity under subsection (a)(1)(iii)."],[0,"(b) Individuals eligible for supplemental annuities"],[0,"An individual who—"],[1,"(i) has attained age 60 and completed thirty years of service or attained age 65;"],[1,"(ii) has completed twenty-five years of service;"],[1,"(iii) is entitled to the payment of an annuity under subsection (a)(1);"],[1,"(iv) had a current connection with the railroad industry at the time such annuity began to accrue; and"],[1,"(v) has performed compensated service in at least one month prior to October 1, 1981;"],[0,"shall, subject to the conditions set forth in subsections (e) and (h), be entitled to a supplemental annuity in the amount provided under section 231b of this title: Provided, however, That in cases where an individual's annuity under subsection (a)(1) begins to accrue on other than the first day of the month, the amount of any supplemental annuity to which he is entitled for that month shall be reduced by one-thirtieth for each day with respect to which he is not entitled to an annuity under subsection (a)(1)."],[0,"(c) Spouses eligible for annuities"],[0,"(1) The spouse of an individual, if—"],[1,"(i) such individual (A) is entitled to an annuity under subsection (a)(1) and (B) has attained the age of 60 and has completed thirty years of service or has attained the age of 62, and"],[1,"(ii) such spouse (A) has attained retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]), or (B) has attained the age of 60 and such individual has completed thirty years of service, or (C), in the case of a wife, has in her care (individually or jointly with her husband) a child who meets the qualifications prescribed in paragraph (iii) of subsection (d)(1) (without regard to the provisions of clause (B) of such paragraph),"],[0,"shall, subject to the conditions set forth in subsections (e), (f), and (h), be entitled to a spouse's annuity, if he or she has filed application therefor, in the amount provided under section 231c of this title."],[0,"(2) A spouse who would be entitled to an annuity under subdivision (1) or a divorced wife who would be entitled to an annuity under subdivision (4) if he or she had attained retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]) may elect upon or after attaining the age of 62 to receive such annuity, but the annuity in any such case shall be reduced by 1/144 for each of the first 36 months that the spouse or divorced wife is under retirement age (as defined in section 216(l) of the Social Security Act) when the annuity begins to accrue and by 1/240 for each additional month that the spouse or divorced wife is under retirement age (as defined in section 216(l) of the Social Security Act) when the annuity begins to accrue, except that the annuity of a divorced wife who was previously entitled to a spouse annuity which was reduced under this subdivision shall be reduced by the same percentage as was applicable to the spouse annuity."],[0,"(3) For the purposes of this subchapter, the term \"spouse\" shall mean the wife or husband of an annuitant under subsection (a)(1) who (i) was married to such annuitant for a period of not less than one year immediately preceding the day on which the application for a spouse's annuity is filed, or in the month prior to his or her marriage to such annuitant was eligible for an annuity under paragraph (i) or (iv) of subsection (d)(1) or, on the basis of disability, under paragraph (iii) thereof, or is the parent of such annuitant's son or daughter; and (ii) in the case of a husband, was receiving at least one-half of his support from his wife at the time his wife's annuity under subsection (a)(1) began."],[0,"(4) The \"divorced wife\" (as defined in section 216(d) of the Social Security Act [42 U.S.C. 416(d)]) of an individual, if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/231a?type=usc&year=mostrecent&link-type=html"},"head":"§231a. Annuity eligibility requirements","tname":"Railroads","by":{"0":"3, 3, 3","1":"2"}},{"t":"usc","label":"45 U.S.C. § 231b","url":"https://www.law.cornell.edu/uscode/text/45/231b","subs":["(b)"],"stext":{"head":"§231b. Computation of annuities","paras":[[0,"(a) Amount"],[0,"(1) The annuity of an individual under section 231a(a)(1) of this title shall be in an amount equal to the amount (before any reduction on account of age and before any deductions on account of work) of the old-age insurance benefit or disability insurance benefit to which such individual would have been entitled under the Social Security Act [42 U.S.C. 301 et seq.] if all of his or her service as an employee after December 31, 1936, had been included in the term \"employment\" as defined in that Act."],[0,"(2) For purposes of this subsection, individuals entitled to an annuity under section 231a(a)(1)(ii) of this title shall, except for the purposes of recomputations in accordance with section 215(f) of the Social Security Act [42 U.S.C. 415(f)], be deemed to have attained retirement age (as defined by section 216(l) of the Social Security Act [42 U.S.C. 416(l)]). For purposes of this subsection, individuals entitled to an annuity under paragraph (iv) or (v) of section 231a(a)(1) of this title shall be deemed to be entitled to a disability insurance benefit under section 223 of the Social Security Act [42 U.S.C. 423]."],[0,"(3) If an individual entitled to an annuity under section 231a(a)(1)(i) or (iii) of this title on the basis of less than ten years of service is entitled to a benefit under section 202(a), section 202(b), or section 202(c) of the Social Security Act [42 U.S.C. 402(a), (b), (c)] which began to accrue before the annuity under section 231a(a)(1)(i) or (iii) of this title, the annuity amount provided such individual under this subsection, shall be computed as though the annuity under this subchapter began to accrue on the later of (A) the date on which the benefit under section 202(a), section 202(b), or section 202(c) of the Social Security Act began, or (B) the date on which the individual first met the conditions for entitlement to an age reduced annuity under this subchapter other than the conditions set forth in sections 231a(e)(1) and 231a(e)(2) of this title and the requirement that an application be filed."],[0,"(b) Increased annuities under subsection (a)"],[0,"(1) The amount of the annuity of an individual provided under subsection (a) shall be increased by an amount equal to seven-tenths of 1 per centum of the product which is obtained by multiplying such individual's \"years of service\" by such individual's \"average monthly compensation\" as determined under this subsection. The annuity amount payable to the individual under this subsection shall be reduced by 25 per centum of the annuity amount computed for such individual under subsection (h)(1) or (h)(2), and subsection (h)(5), of this section without regard to section 231f(c)(1) of this title. An individual's \"average monthly compensation\" for purposes of this subsection shall be the quotient obtained by dividing by 60 such individual's total compensation for the 60 months, consecutive or otherwise, during which such individual received that individual's highest monthly compensation, except that no part of any month's compensation in excess of the maximum amount creditable for any individual for such month under subsection (j) of this section shall be recognized. In determining the months of compensation to be used for purposes of this subsection, the total compensation reported for the individual under section 231h of this title or credited to such individual under subsection (j) of this section for a year divided by the number of months of service credited to such individual under subsection (i) of this section with respect to such year shall be considered the monthly compensation of the individual for each month of service in any year for which records of the Board do not show the amount of compensation paid to the individual on a monthly basis. If the \"average monthly compensation\" computed under this subsection is not a multiple of $1, it shall be rounded to the next lower multiple of $1."],[0,"(2) For purposes of subdivision (1) of this subsection, in determining \"average monthly compensation\" for an individual who has not engaged in employment for an employer in the 60-month period preceding the month in which such individual's annuity began to accrue, and whose major employment during such 60-month period was for a United States department or agency named in section 231(o) of this title, the amount of compensation used with respect to each month used in making such determination shall be the product of—"],[1,"(i) the compensation credited to such individual for such month under paragraph (1) of this subsection; and"],[1,"(ii) the quotient obtained by dividing—"],[2,"(I) the average of total wages (as determined under section 215(b)(3)(A)(ii)(I) of the Social Security Act [42 U.S.C. 415(b)(3)(A)(ii)(I)]) for the second calendar year preceding the earliest of the year of the individual's death or the year in which an annuity begins to accrue to such individual (disregarding an annuity based on disability which is terminated because such individual has recovered from such disability if such individual engages in any regular employment after such termination); by"],[2,"(II) the average of total wages (as determined under section 215(b)(3)(A)(ii)(II) of the Social Security Act [42 U.S.C. 415(b)(3)(A)(ii)(II)]) for the calendar year during which such month occurred, unless such month occurred prior to calendar year 1951, in which case, the average of total wages so determined for 1951."],[0,"In no event shall \"average monthly compensation\" determined for an individual under this subdivision exceed the maximum \"average monthly compensation\" which can be determined under subdivision (1) of this subsection for any person retiring January 1 of the year in which such individual's annuity began to accrue."],[0,"(c), (d) Repealed. Pub. L. 97–35, title XI, §1118(b), Aug. 13, 1981, 95 Stat. 631"],[0,"(e) Supplemental annuities"],[0,"The supplemental annuity of an individual under section 231a(b) of this title shall be $23 plus an additional amount of $4 for each year of service that the individual has in excess of 25 years, but in no case shall the supplemental annuity exceed $43."],[0,"(f) Reductions in annuities"],[0,"(1) If, in the case of an individual whose annuity under section 231a(a)(1) of this title began to accrue prior to January 1, 1983, the annuity (before any reduction due to such individual's entitlement to a monthly insurance benefit under the Social Security Act [42 U.S.C. 301 et seq.] and disregarding any amount provided by subsection (h) of this section) plus the supplemental annuity to which such individual is entitled for any month under this subchapter, together with the annuity, if any, of the spouse of such individual (before any reduction due to such spouse's entitlement to a wife's or husband's insurance benefit under the Social Security Act and disregarding any amount provided by section 231c(e) of this title), before any reductions under the provisions of section 231a(f) of this title is less than the total amount which would have been payable to such individual and his spouse for such month, on the basis of the individual's compensation and years of service, under the provisions of the Railroad Retirement Act of 1937 as in effect on December 31, 1974 [45 U.S.C. 228a et seq.], disregarding, for purposes of the computations under such Railroad Retirement Act of 1937 compensation for any month after December 31, 1974, in excess of one-twelfth of the maximum annual taxable \"wages\" (as defined in section 3121 of the Internal Revenue Code of 1986 [26 U.S.C. 3121]) for the calendar year 1974, the annuity of such individual and the annuity of such spouse, if any, shall be increased proportionately so as to equal such total amount. For the purpose of computing amounts under this subdivision, the Board shall have the authority to approximate the effect of the reductions prescribed by sections 3(a)(2) and 3(a)(3) of the Railroad Retirement Act of 1937 [45 U.S.C. 228c(a)(2), (a)(3)]. For purposes of computing amounts payable under the Railroad Retirement Act of 1937, any increases in the amounts determined under the first proviso of section 3(e) of such Act which would have become effective after December 31, 1974, shall be disregarded."],[0,"(2) If for any month in which an annuity accrues and is payable under this subchapter the annuity to which an individual is entitled under this subchapter (or would have been entitled except for a reduction pursuant to a joint and survivor election), together with the annuity, if any, of the spouse and divorced wife of such individual, is less than the total amount, or the additional amount, which would have been payable to all persons for such month under the Social Security Act [42 U.S.C. 301 et seq.] if such individual's service as an employee after December 31, 1936, were included in the term \"employment\" as defined in that Act, the annuities of the individual and spouse shall be increased proportionately to such total amount, or such additional amount: Provided, however, That if an annuity accrues to an individual or a spouse for a part of a month, the amount payable for such part of a month under this subdivision shall be one-thirtieth of the amount payable under this subdivision for an entire month, multiplied by the number of days in such part of a month. For purposes of this subdivision, (i) persons not entitled to an annuity under section 231a of this title shall not be included in the computation under this subdivision except a spouse who could qualify for an annuity under section 231a(c) of this title if the individual from whom the spouse's annuity under this subchapter would derive had attained age 60 or 62, as the case may be, and such individual's children who meet the definition as such contained in section 216(e) of the Social Security Act [42 U.S.C. 416(e)]; (ii) after an annuity has been certified for payment and this subdivision was inapplicable after allowing for any waiting period under section 223(c)(2) of the Social Security Act [42 U.S.C. 423(c)(2)], and after having considered the inclusion of all persons who were then eligible for inclusion in the computation under this subdivision, or was then applicable but later became inapplicable, any recertification in such annuity under this subdivision shall not take into account persons not entitled to an annuity under section 231a of this title except a spouse who could qualify for an annuity under section 231a(c) of this title when she attains age 60 or 62, as the case may be, if the individual from whom the spouse's annuity would derive had attained age 60 or 62, as the case may be, and who was married to such individual at the time he applied for his annuity; and (iii) in computing the amount to be paid under this subdivision the only benefits under title II of the Social Security Act [42 U.S.C. 401 et seq.] which shall be considered shall be those to which the persons included in the computation are entitled."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/231b?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§231b. Computation of annuities","tname":"Railroads","by":{"0":"3, 5, 26","1":"33"}},{"t":"usc","label":"45 U.S.C. § 231f","url":"https://www.law.cornell.edu/uscode/text/45/231f","subs":["(b)(6)"],"by":{"0":"4, 4"}},{"t":"usc","label":"45 U.S.C. § 231h","url":"https://www.law.cornell.edu/uscode/text/45/231h","by":{"0":"4"}},{"t":"usc","label":"45 U.S.C. § 352","url":"https://www.law.cornell.edu/uscode/text/45/352","by":{"0":"3"}},{"t":"reg","label":"20 C.F.R. § 200.1","url":"https://www.ecfr.gov/current/title-20/section-200.1","subs":["(a)(3)"],"by":{"0":"4"}},{"t":"reg","label":"26 C.F.R. § 31.3202-1","url":"https://www.ecfr.gov/current/title-26/section-31.3202-1","by":{"0":"4"}},{"t":"reg","label":"26 C.F.R. § 31.3231","url":"https://www.ecfr.gov/current/title-26/section-31.3231","subs":["(e)"],"by":{"0":"35, 46, 9, 34, 16, 34, 35, 43"}},{"t":"reg","label":"26 C.F.R. § 410.5","url":"https://www.ecfr.gov/current/title-26/section-410.5","by":{"0":"passim"}},{"t":"reg","label":"59 Fed. Reg. 66188","url":"https://www.govinfo.gov/link/fr/59/66188","by":{"0":"35, 9, 10"}},{"t":"case","label":"Branch v. Smith","cite":"538 U.S. 254","y":2003,"id":"2002/01-1437","sc":1,"sum":"The Court held, 9-0, that the District Court properly enjoined enforcement of the state- court plan that lacked the required timely preclearance.","sumSrc":"Oyez","by":{"1":"20","2":"31"}},{"t":"case","label":"CFTC v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"sum":"Section 14 of the Commodity Exchange Act (CEA) provides that any person injured by a commodity broker's violation of the Act or regulations of the Commodity Futures Trading Commission (CFTC) may apply to the CFTC for an order directing the offender to pay reparations to the complainant and may enforce that order in federal district court. The CFTC promulgated a regulation that allows it in a reparations proceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Christopher v. SmithKline Beechman Corp.","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"sum":"The Court held that the Secretary of Labor's definition of \"outside salesman\" apply to pharmaceutical sales representatives under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"1":"22","2":"27","3":"19"}},{"t":"case","label":"Cottage Sav. Ass’n v. Commissioner","cite":"499 U.S. 554","y":1991,"id":"1990/89-1965","sc":1,"sum":"In a 7-to-2 decision, the Supreme Court held that the definition of \"substantially identical\" under the FHLBB regulations was intentionally flexible and broad enough to include even properties that were \"materially different\" for IRS purposes.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Director of Revenue v. CoBank ACB","cite":"531 U.S. 316","y":2001,"id":"2000/99-1792","sc":1,"sum":"The Court held that banks for cooperatives are subject to taxation. Justice Thomas wrote for the Court that nothing in the 1985 amendments to the Farm Credit Act indicated a repeal of the previous express approval of state taxation and that the structure of the Act indicated by negative implication that banks for cooperatives were not entitled to immunity.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Dotson v. United States","cite":"87 F.3d 682","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/87/682/","by":{"1":"32","2":"45"}},{"t":"case","label":"Gerbec v. United States","cite":"164 F.3d 1015","y":1999,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/164/1015/","by":{"1":"32","2":"45"}},{"t":"case","label":"Groman v. Commissioner","cite":"302 U.S. 82","y":1937,"id":"scdb/1937-021","sc":1,"sum":"that G was not \"a party\" to the reorganization and that the shares of G's preference stock received by I shareholdersfrom 0 were a basis for computing taxable gain. Revenue Act of 1928, § 112. P. 88. 86 F. (2d) 670, affirmed. CERTIORARI, 301 U. S. 677, to review a judgment overruling an order of the Board of Tax Appeals and sustaining an income tax deficiency assessment. Mr. Egbert Robertson, with whom Mr. James C. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22","2":"27"}},{"t":"case","label":"Kellogg Brown & Root Servs., Inc. v. Carter","cite":"135 S. Ct. 1970","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1970/","sc":1,"by":{"1":"25","2":"28, 33"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Trust","cite":"136 S. Ct. 1938","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Redfield v. Insurance Co. of N. Am.","cite":"940 F.2d 542","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/940/542/","by":{"1":"32","2":"45"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"sum":"An offense constitutes \"burglary\" under §924(e) if, regardless of its exact definition or label, it has the basic elements of a \"generic\" burglary-i. e., an unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime-or if the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Texas Dep’t of Hous. & Cmty. Affairs v. Inclusive Cmtys. Project, Inc.","cite":"135 S. Ct. 2507","y":2015,"id":"2014/13-1371","sc":1,"sum":"The Court determined that evidence of disparate impact is sufficient to allege a claim that the defendant violated the Fair Housing Act.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"United States v. Cleveland Indians Baseball Co.","cite":"532 U.S. 200","y":2001,"id":"2000/00-203","sc":1,"op":5,"ar":5,"sum":"The Court held that back wages are subject to FICA and FUTA taxes by reference to the year the wages are in fact paid. \"Although the regulations, like the statute, do not specifically address backpay, the Internal Revenue Service has consistently interpreted them to require taxation of back wages according to the year the wages are actually paid, regardless of when those wages were earned or should have been paid,\" wrote Justice Ginsburg for the Court.","sumSrc":"Oyez","by":{"1":"24","2":"21, 30, 32, 35, 36, 37, 39, 40","3":"5, 6, 10, 11"}},{"t":"case","label":"United States v. Riverside Bayview Homes, Inc.","cite":"474 U.S. 121","y":1985,"id":"1985/84-701","sc":1,"sum":"The Clean Water Act prohibits any discharge of dredged or fill materials into \"navigable waters\"-defined as the \"waters of the United States\"unless authorized by a permit issued by the Army Corps of Engineers (Corps). Construing the Act to cover all \"freshwater wetlands\" that are adjacent to other covered waters, the Corps issued a regulation defining such wetlands as \"those areas that are inundated or saturated by …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22","2":"31"}},{"t":"case","label":"United States v. Stewart","cite":"311 U.S. 60","y":1940,"id":"scdb/1940-007","sc":1,"sum":"Construing Revenue Acts of 1916 and 1928 in pari materia.","sumSrc":"brief:2","by":{"1":"21","2":"31-32"}},{"t":"case","label":"Wisconsin Central Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"op":2,"ar":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"1":"3, 13, 21","2":"5, 15, 16, 18, 23, 24, 30, 31, 34, 38, 39, 40, 42, 46, 52, 53"}},{"t":"law","label":"Pub. L. No. 94-93","url":"https://www.govinfo.gov/link/statute/89/466","by":{"1":"6","2":"12"}},{"t":"law","label":"Pub. L. No. 94-547","url":"https://www.govinfo.gov/link/statute/90/2526","by":{"1":"8"}},{"t":"law","label":"Pub. L. No. 97-123","url":"https://www.govinfo.gov/link/statute/95/1659","by":{"1":"8"}},{"t":"usc","label":"45 U.S.C. § 51","url":"https://www.law.cornell.edu/uscode/text/45/51","stext":{"head":"§51. Liability of common carriers by railroad, in interstate or foreign commerce, for injuries to employees from negligence; employee defined","paras":[[0,"Every common carrier by railroad while engaging in commerce between any of the several States or Territories, or between any of the States and Territories, or between the District of Columbia and any of the States or Territories, or between the District of Columbia or any of the States or Territories and any foreign nation or nations, shall be liable in damages to any person suffering injury while he is employed by such carrier in such commerce, or, in case of the death of such employee, to his or her personal representative, for the benefit of the surviving widow or husband and children of such employee; and, if none, then of such employee's parents; and, if none, then of the next of kin dependent upon such employee, for such injury or death resulting in whole or in part from the negligence of any of the officers, agents, or employees of such carrier, or by reason of any defect or insufficiency, due to its negligence, in its cars, engines, appliances, machinery, track, roadbed, works, boats, wharves, or other equipment."],[0,"Any employee of a carrier, any part of whose duties as such employee shall be the furtherance of interstate or foreign commerce; or shall, in any way directly or closely and substantially, affect such commerce as above set forth shall, for the purposes of this chapter, be considered as being employed by such carrier in such commerce and shall be considered as entitled to the benefits of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/51?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§51. Liability of common carriers by railroad, in interstate or foreign commerce, for injuries to employees from negligence; employee defined","tname":"Railroads","by":{"1":"10","2":"passim"}},{"t":"usc","label":"26 U.S.C. § 3101","url":"https://www.law.cornell.edu/uscode/text/26/3101","stext":{"head":"§3101. Rate of tax","paras":[[0,"(a) Old-age, survivors, and disability insurance"],[0,"In addition to other taxes, there is hereby imposed on the income of every individual a tax equal to 6.2 percent of the wages (as defined in section 3121(a)) received by the individual with respect to employment (as defined in section 3121(b))."],[0,"(b) Hospital insurance"],[0,"(1) In general"],[1,"In addition to the tax imposed by the preceding subsection, there is hereby imposed on the income of every individual a tax equal to 1.45 percent of the wages (as defined in section 3121(a)) received by him with respect to employment (as defined in section 3121(b))."],[0,"(2) Additional tax"],[1,"In addition to the tax imposed by paragraph (1) and the preceding subsection, there is hereby imposed on every taxpayer (other than a corporation, estate, or trust) a tax equal to 0.9 percent of wages which are received with respect to employment (as defined in section 3121(b)) during any taxable year beginning after December 31, 2012, and which are in excess of—"],[2,"(A) in the case of a joint return, $250,000,"],[2,"(B) in the case of a married taxpayer (as defined in section 7703) filing a separate return, ½ of the dollar amount determined under subparagraph (A), and"],[2,"(C) in any other case, $200,000."],[0,"(c) Relief from taxes in cases covered by certain international agreements"],[0,"During any period in which there is in effect an agreement entered into pursuant to section 233 of the Social Security Act with any foreign country, wages received by or paid to an individual shall be exempt from the taxes imposed by this section to the extent that such wages are subject under such agreement exclusively to the laws applicable to the social security system of such foreign country."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3101. Rate of tax","tname":"Internal Revenue Code","by":{"1":"9","2":"passim"}},{"t":"usc","label":"29 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/29/151","by":{"1":"17"}},{"t":"law","label":"Pub. L. No. 98-76","url":"https://www.govinfo.gov/link/statute/97/411","by":{"1":"8","2":"12"}},{"t":"usc","label":"45 U.S.C. § 351","url":"https://www.law.cornell.edu/uscode/text/45/351","stext":{"head":"§351. Definitions","paras":[[0,"For the purposes of this chapter, except when used in amending the provisions of other Acts—"],[0,"(a) The term \"employer\" means any carrier (as defined in subsection (b) of this section), and any company which is directly or indirectly owned or controlled by one or more such carriers or under common control therewith, and which operates any equipment or facility or performs any service (except trucking service, casual service, and the casual operation of equipment or facilities) in connection with the transportation of passengers or property by railroad, or the receipt, delivery, elevation, transfer in transit, refrigeration or icing, storage, or handling of property transported by railroad, and any receiver, trustee, or other individual or body, judicial or otherwise, when in the possession of the property or operating all or any part of the business of any such employer: Provided, however, That the term \"employer\" shall not include any street, interurban, or suburban electric railway, unless such railway is operating as a part of a general steam-railroad system of transportation, but shall not exclude any part of the general steam-railroad system of transportation now or hereafter operated by any other motive power. The Surface Transportation Board is hereby authorized and directed upon request of the Railroad Retirement Board, or upon complaint of any party interested, to determine after hearing whether any line operated by electric power falls within the terms of this proviso. The term \"employer\" shall also include railroad associations, traffic associations, tariff bureaus, demurrage bureaus, weighing and inspection bureaus, collection agencies, and other associations, bureaus, agencies, or organizations controlled and maintained wholly or principally by two or more employers as hereinbefore defined and engaged in the performance of services in connection with or incidental to railroad transportation; and railway labor organizations, national in scope, which have been or may be organized in accordance with the provisions of the Railway Labor Act [45 U.S.C. 151 et seq.], and their State and National legislative committees and their general committees and their insurance departments and their local lodges and divisions, established pursuant to the constitution and bylaws of such organizations. The term \"employer\" shall not include any company by reason of its being engaged in the mining of coal, the supplying of coal to an employer where delivery is not beyond the mine tipple, and the operation of equipment or facilities therefor, or in any of such activities."],[0,"(b) The term \"carrier\" means a railroad subject to the jurisdiction of the Surface Transportation Board under part A of subtitle IV of title 49."],[0,"(c) The term \"company\" includes corporations, associations, and joint-stock companies."],[0,"(d) The term \"employee\" (except when used in phrases establishing a different meaning) means any individual who is or has been (i) in the service of one or more employers for compensation, or (ii) an employee representative. The term \"employee\" shall include an employee of a local lodge or division defined as an employer in subsection (a) only if he was in the service of a carrier on or after August 29, 1935. The term \"employee\" includes an officer of an employer."],[0,"The term \"employee\" shall not include any individual while such individual is engaged in the physical operations consisting of the mining of coal, the preparation of coal, the handling (other than movement by rail with standard railroad locomotives) of coal not beyond the mine tipple, or the loading of coal at the tipple."],[0,"(e) An individual is in the service of an employer whether his service is rendered within or without the United States if (i) he is subject to the continuing authority of the employer to supervise and direct the manner of rendition of his service, or he is rendering professional or technical services and is integrated into the staff of the employer, or he is rendering, on the property used in the employer's operations, other personal services the rendition of which is integrated into the employer's operations, and (ii) he renders such service for compensation: Provided, however, That an individual shall be deemed to be in the service of an employer, other than a local lodge or division or a general committee of a railway-labor-organization employer, not conducting the principal part of its business in the United States only when he is rendering service to it in the United States; and an individual shall be deemed to be in the service of such a local lodge or division only if (1) all, or substantially all, the individuals constituting its membership are employees of an employer conducting the principal part of its business in the United States; or (2) the headquarters of such local lodge or division is located in the United States; and an individual shall be deemed to be in the service of such a general committee only if (1) he is representing a local lodge or division described in clauses (1) or (2) immediately above; or (2) all, or substantially all, the individuals represented by it are employees of an employer conducting the principal part of its business in the United States; or (3) he acts in the capacity of a general chairman or an assistant general chairman of a general committee which represents individuals rendering service in the United States to an employer, but in such case if his office or headquarters is not located in the United States and the individuals represented by such general committee are employees of an employer not conducting the principal part of its business in the United States, only such proportion of the remuneration for such service shall be regarded as compensation as the proportion which the mileage in the United States under the jurisdiction of such general committee bears to the total mileage under its jurisdiction, unless such mileage formula is inapplicable, in which case the Board may prescribe such other formula as it finds to be equitable, and if the application of such mileage formula, or such other formula as the Board may prescribe, would result in the compensation of the individual being less than 10 per centum of his remuneration for such service no part of such remuneration shall be regarded as compensation: Provided further, That an individual not a citizen or resident of the United States shall not be deemed to be in the service of an employer when rendering service outside the United States to an employer who is required under the laws applicable in the place where the service is rendered to employ therein, in whole or in part, citizens or residents thereof."],[0,"(f) The term \"employee representative\" means any officer or official representative of a railway labor organization other than a labor organization included in the term employer as defined in subsection (a) who before or after August 29, 1935, was in the service of an employer as defined in said subsection and who is duly authorized and designated to represent employees in accordance with the Railway Labor Act [45 U.S.C. 151 et seq.], and any individual who is regularly assigned to or regularly employed by such officer or official representative in connection with the duties of his office."],[0,"(g) The term \"employment\" means service performed as an employee. For the purposes of determining eligibility for and the amount of benefits and the amount of contributions due pursuant to this chapter, employment after June 30, 1940, in the service of a local lodge or division of a railway-labor-organization employer or as an employee representative shall be disregarded. For purposes of determining eligibility for and the amount of benefits and the amount of contributions due pursuant to this chapter, employment as a delegate to a national or international convention of a railway labor organization defined as an \"employer\", in subsection (a) of this section, shall be disregarded if the individual having such employment has not previously rendered service, other than as such a delegate, which may be included in his \"years of service\" for purposes of the Railroad Retirement Act [45 U.S.C. 231 et seq.]."],[0,"(h) The term \"registration period\" means, with respect to any employee, the period which begins with the first day for which such employee registers at an employment office in accordance with such regulations as the Board may prescribe, and ends with whichever is the earlier of (i) the thirteenth day thereafter, or (ii) the day immediately preceding the day for which he next registers at a different employment office; and thereafter each period which begins with the first day for which he next registers at an employment office after the end of his last preceding registration period which began with a day for which he registered at an employment office and ends with whichever is the earlier of (i) the thirteenth day thereafter, or (ii) the day immediately preceding the day for which he next registers at a different employment office."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/351?type=usc&year=mostrecent&link-type=html"},"head":"§351. Definitions","tname":"Railroads","by":{"1":"20","2":"8, 19, 20, 31, 33"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","stext":{"head":"§301. Authorization of appropriations","paras":[[0,"For the purpose of enabling each State, as far as practicable under the conditions in such State, to furnish financial assistance to aged needy individuals, there is hereby authorized to be appropriated for each fiscal year a sum sufficient to carry out the purposes of this subchapter. The sums made available under this section shall be used for making payments to States which have submitted, and had approved by the Secretary of Health and Human Services (hereinafter referred to as the \"Secretary\"), State plans for old-age assistance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/301?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§301. Authorization of appropriations","tname":"The Public Health and Welfare","by":{"1":"13","2":"14, 15, 30, 34, 35"}},{"t":"reg","label":"59 Fed. Reg. 66,149","url":"https://www.govinfo.gov/link/fr/59/66149","by":{"1":"10"}},{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"137 S. Ct. 1652","y":2017,"id":"2016/16-74","sc":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"2":"19, 27, 34"}},{"t":"case","label":"Alaska v. Federal Subsistence Bd.","cite":"544 F.3d 1089","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/544/1089/","by":{"2":"56"}},{"t":"case","label":"Anderson v. United States","cite":"929 F.2d 648","y":1991,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/929/648/","by":{"2":"45"}},{"t":"case","label":"Bowen v. Georgetown Univ. Hosp.","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"sum":"Under the Medicare program, the Government reimburses health care providers for expenses incurred in providing medical services to Medicare beneficiaries. The Medicare Act in 42 U. S. C. § 1395x(v)(1)(A) authorizes the Secretary of Health and Human Services (Secretary) to promulgate cost-reimbursement regulations and also provides that \"[s]uch regulations shall... (ii) provide for the making of suitable retroactive …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"56"}},{"t":"case","label":"Bowen v. Massachusetts","cite":"487 U.S. 879","y":1988,"id":"1987/87-712","sc":1,"sum":"The federal contribution (referred to as a \"reimbursement\") to a State's Medicaid program takes the form of advances based on the State's estimate of its future expenditures for covered services. Overpayments may be withheld from future advances, or, if a disallowance dispute develops, may be retained by the State at its option pending resolution of the dispute. After Massachusetts was reimbursed by the Department …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Bowers v. Kerbaugh-Empire Co.","cite":"271 U.S. 170","y":1926,"id":"scdb/1925-114","sc":1,"sum":"that the difference, resulting from the depreciation, between the amount borrowed and the amount repaid, in American money, was not taxable as \"income.\" P. 173. 300 Fed. 938, affirmed. ERROR to a judgment of the District Court recovered by the Company from the Collector in an action for money paid under protest as income tax. Assistant Attorney General Wilieblandt, with whom Solicitor General Mitchell and Messrs. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"44"}},{"t":"case","label":"Burgess v. United States","cite":"553 U.S. 124","y":2008,"id":"2007/06-11429","sc":1,"sum":"The Court upheld the sentencing hike, stating that the definition of a felony drug offense in 12 U.S.C. 841 as punishable by imprisonment for more than one year was controlling regardless of whether South Carolina classified the offense as a felony or a misdemeanor.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Burlington N. & S.F. Ry. Co. v. White","cite":"548 U.S. 53","y":2006,"id":"2005/05-259","sc":1,"sum":"In a decision authored by Justice Stephen Breyer and joined by Chief Justice Roberts and six other justices, the Court held that in order to prevail on a claim of retaliatory discrimination, \"a plaintiff must show that a reasonable employee would have found the challenged action materially adverse, which in this context means it well might have dissuaded a reasonable worker from making or supporting a charge of discrimination.\" (internal citations omitted) Justice Samuel Alito wrote separately, agreeing with the result but arguing that the test adopted by the other members of the Court would eventually prove problematic.","sumSrc":"Oyez","by":{"2":"27-28, 31, 48"}},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"sum":"The Court found that only tribes under federal jurisdiction at the time of the Indian Reorganization Act of 1934 are subject to taking by the federal government.","sumSrc":"Oyez","by":{"2":"21, 47"}},{"t":"case","label":"Central Illinois Pub. Serv. Co. v. United States","cite":"435 U.S. 21","y":1978,"id":"1977/76-1058","sc":1,"sum":"Reimbursement for 1963 lunch expenses of employees on nonovernight company travel did not constitute \"wages\" subject to withholding by their employer within the meaning of § 3401 (a) of the Internal Revenue Code of 1954, which defines \"wages\" for purposes of the withholding tax provisions to include \"all remuneration... for services performed by an employee for his employer.... \" Pp. 24-33. 540 F. 2d 300, reversed. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"44"}},{"t":"case","label":"Chesapeake & O. Ry. Co. v. United States","cite":"571 F.2d 1190","y":1977,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/571/1190/","by":{"2":"3, 9"}},{"t":"case","label":"Chevron U.S.A. Inc. v. Echazabal","cite":"536 U.S. 73","y":2002,"id":"2001/00-1406","sc":1,"sum":"The Court held that the ADA did not preclude the EEOC's regulation allowing the harm-to-self defense. The Court reasoned that deference applied to the regulation because it made sense of the statutory defense for qualification standards that are job-related and consistent with business necessity.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Chicago & N.W. Ry. Co. v. United Transp. Union","cite":"402 U.S. 570","y":1971,"id":"1970/189","sc":1,"sum":"Petitioner railroad brought this suit (after formal procedures of the Railway Labor Act had been exhausted) to enjoin a threatened strike by respondent Union, charging that the Union had failed to perform its obligations under § 2 First of the Railway Labor Act \"to exert every reasonable effort to make and maintain agreements concerning rates of pay, rules, and working conditions.\" The Union answered that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"Christensen v. Harris Cty.","cite":"529 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"sum":"The Court held 6-3 that \"[n]othing in the FLSA or its implementing regulations prohibits a public employer from compelling the use of compensatory time.\" Justice Thomas wrote for the Court that, \"under the FLSA, an employer is free to require an employee to take time off work, and an employer is also free to use the money it would have paid in wages to cash out accrued compensatory time.","sumSrc":"Oyez","by":{"2":"53"}},{"t":"case","label":"Commissioner v. Schleier","cite":"515 U.S. 323","y":1995,"id":"1994/94-500","sc":1,"sum":"On(ltossihAppfqhaooDuaitnnisEdddtchaAe1eltae9nne)i8t.mdt6l)iiqndiAufnuiaetncifmiddltdaueeaaterdretgraeedetlddhtsheTiedpnaaaocsCxAmorotgmgiaCmoregeoonmes,uDstsiarsoitsxsisfnhicpoacorrrnnoiueomemltcdraueiewnrieshnadastat,ihruivndoeeEegndtsrbhi,bacaiaenchcetdkoneEhpSnfeamicticyenhripsceeltlelpnciouinceoeydygirrmevtidenote(dohhnnatate,siictnrAbeeirn,siuucnceattloatistmnfonsltegefoeemrtr,1taie9trnrnh6neegd7et-sareegcerek …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46, 54"}},{"t":"case","label":"Consolidated Rail Corp. v. Gottshall","cite":"512 U.S. 532","y":1994,"id":"1993/92-1956","sc":1,"sum":"The Court held that this test would best distinguish between genuine and fraudulent claims, and provide relief in the case of injury. The Court rejected the Third Circuit's holding that employers were liable for causing foreseeably stressful conditions, reasoning that this would extend to many types of everyday employment.","sumSrc":"Oyez","by":{"2":"6, 40"}},{"t":"case","label":"Dodd v. United States","cite":"545 U.S. 353","y":2005,"id":"2004/04-5286","sc":1,"sum":"The Court held that the text of the federal law \"unequivocally\" stated that the one-year limitation period begins to run on the date on which the Court \"initially recongized\" the right, not the date on which that right was made retroactive.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"2":"54"}},{"t":"case","label":"Hilton v. South Carolina Pub. Rys. Comm’n","cite":"502 U.S. 197","y":1991,"id":"1991/90-848","sc":1,"sum":"FELA creates a cause of action against a state-owned railroad, enforceable in state court.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6","3":"3"}},{"t":"case","label":"Iselin v. United States","cite":"270 U.S. 245","y":1926,"id":"scdb/1925-076","sc":1,"op":1,"sum":"1. Par. 3 of § 800(a) of Revenue Act of 1918, laying taxes on theater and opera tickets sold at newstands, hotels, etc., for more than the “established price” at the ticket office of the theater or opera house, held inapplicable to sale by a stockholder of box tickets, issued as an incident of his investment in an opera house company, which were not sold at the box-office and for which there was no established price.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Jones & Laughlin Steel Corp. v. Pfeifer","cite":"462 U.S. 523","y":1983,"id":"1982/82-131","sc":1,"sum":"Respondent was injured in the course of his employment while employed by petitioner as a loading helper on petitioner's coal barge in Pennsylvania. The injury made respondent permanently unable to return to his job or to perform other than light work. Respondent brought an action in Federal District Court against petitioner, alleging that his injury had been \"caused by the negligence of the vessel\" within the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"op":3,"sum":"The Court held that the policy of equitable tolling does not apply to the statute of limitations outlined in the Hauge Convention's provision on international child abduction.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"Meese v. Keene","cite":"481 U.S. 465","y":1987,"id":"1986/85-1180","sc":1,"sum":"The Foreign Agents Registration Act of 1938 (Act) requires registration, reporting, and disclosure by persons engaging in propaganda on behalf of foreign powers. The Act uses the term \"political propaganda\" to identify those expressive materials subject to its requirements, and defines the term as, inter alia, any communication intended to influence the United States' foreign policies. Appellee, a member of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Michigan v. EPA","cite":"135 S. Ct. 2699","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2699/","sc":1,"by":{"2":"54"}},{"t":"case","label":"Montello Salt Co. v. Utah","cite":"221 U.S. 452","y":1911,"id":"scdb/1910-153","sc":1,"sum":"The words “and including” following a description do not necessarily mean “in addition to,” but may refer to a part of the thing described.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"26","3":"9"}},{"t":"case","label":"New York Cent. R.R. Co. v. Winfield","cite":"244 U.S. 147","y":1917,"id":"scdb/1916-068","sc":1,"op":1,"sum":"The liabilities and obligations of interstate railroad carriers to make compensation for personal injuries suffered by their employees while engaged in interstate commerce are regulated both inclusively and exclusively by the Federal Employers’ Liability Act; and, Congress having thus fully covered the subject, no room exists for state regulation, even in respect of injuries occurring without fault, as to which the …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"20, 40"}},{"t":"case","label":"NLRB v. Great Dane Trailers, Inc.","cite":"388 U.S. 26","y":1967,"id":"1966/781","sc":1,"sum":"Respondent company and a union representing its employees entered into a collective bargaining agreement which contained a provision for employee vacation benefits, to be paid on the Friday nearest July 1 of each year. Most of the employees went on strike May 16, 1963, and many were gradually replaced by respondent. A demand for vacation pay by the strikers on July 12, 1963, was rejected by the company on the ground …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Norfolk & W. Ry. Co. v. Liepelt","cite":"444 U.S. 490","y":1980,"id":"1979/78-1323","sc":1,"sum":"In a wrongful-death action brought under the Federal Employers' Liability Act in an Illinois court, the trial court erred in excluding evidence offered by petitioner-defendant to show the effect of income taxes on the decedent's estimated future earnings, and in refusing petitioner's requested jury instruction that \"your award will not be subject to any income taxes, and you should not consider such taxes in fixing …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6, 41"}},{"t":"case","label":"O’Gilvie v. United States","cite":"519 U.S. 79","y":1996,"id":"1996/95-966","sc":1,"sum":"The Court held that the punitive damages received by the O'Gilvies were not received \"on account of\" personal injuries,\" and therefore the provision did not apply and the damages were taxable.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Pollock v. Farmers’ Loan & Trust Co.","cite":"158 U.S. 601","y":1895,"id":"scdb/1894-236","sc":1,"sum":"Hylton v. United States, 3 Dali. 171, further considered, and, in view of the '' historical evidence cited, shown to have only decided that the' tax on carriages involved was an excise, and was therefore an indirect tax.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Posadas v. National City Bank of New York","cite":"296 U.S. 497","y":1936,"id":"scdb/1935-071","sc":1,"by":{"2":"43"}},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"sum":"The plurality rejected the argument that only actually-navigable waters can be regulated by the Clean Water Act, but also held that the word \"navigable\" in the Act cannot be divested of all meaning. The plurality held that the definitional term \"waters of the United States\" can only refer to \"relatively permanent, standing or flowing bodies of water,\" not \"occasional,\" \"intermittent,\" or \"ephemeral\" flows.","sumSrc":"Oyez","by":{"2":"54"}},{"t":"case","label":"Reiter v. Sonotone Corp.","cite":"442 U.S. 330","y":1979,"id":"1978/78-690","sc":1,"sum":"Consumers who pay a higher price for goods purchased for personal use as a result of antitrust violations sustain an injury in their \"property\" within the meaning of § 4.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"47"}},{"t":"case","label":"Rowan Cos. v. United States","cite":"452 U.S. 247","y":1981,"id":"1980/80-780","sc":1,"sum":"The Treasury Regulations interpreting the definition of \"wages\" in FICA and FUTA to include the value of the meals and lodging are invalid, for they fail to implement the statutory definition in a consistent or reasonable manner. The plain language and legislative histories of the relevant statutes indicate that Congress intended its definition of \"wages\" to be interpreted in the same manner for FICA and FUTA as for …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42, 44, 45, 47, 54, 55","3":"23, 24"}},{"t":"case","label":"Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"sum":"The Court held that there was no reason that time spent waiting could not also be time spent working, especially in cases in which the conditions of employment involve waiting time. Although it can be difficult to determine the facts of a case and whether the activity in question constitutes work, Congress granted the courts the authority to do so.","sumSrc":"Oyez","by":{"2":"55-56"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"Union Pac. R.R. Co. v. United States","cite":"865 F.3d 1045","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/865/1045/","op":3,"by":{"2":"38, 39"}},{"t":"case","label":"United States v. Pierce","cite":"147 F. 199","y":1906,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F./147/199/","by":{"2":"26"}},{"t":"case","label":"West Virginia Univ. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"op":1,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"law","label":"Pub. L. No. 94-92","url":"https://www.govinfo.gov/link/statute/89/461","by":{"2":"12"}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","subs":["(b)(2)"],"by":{"2":"51"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"2":"31"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","by":{"2":"33"}},{"t":"usc","label":"45 U.S.C. § 57","url":"https://www.law.cornell.edu/uscode/text/45/57","by":{"2":"25"}},{"t":"usc","label":"33 U.S.C. § 901","url":"https://www.law.cornell.edu/uscode/text/33/901","by":{"2":"25, 26"}},{"t":"usc","label":"45 U.S.C. § 231231v","url":"https://www.law.cornell.edu/uscode/text/45/231231v","by":{"2":"passim"}},{"t":"usc","label":"2 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/2/1301","subs":["(4)"],"by":{"2":"26"}},{"t":"usc","label":"18 U.S.C. § 1952","url":"https://www.law.cornell.edu/uscode/text/18/1952","by":{"2":"32"}},{"t":"usc","label":"18 U.S.C. § 1953","url":"https://www.law.cornell.edu/uscode/text/18/1953","by":{"2":"32"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(10)"],"by":{"2":"27"}},{"t":"usc","label":"42 U.S.C. § 6903","url":"https://www.law.cornell.edu/uscode/text/42/6903","subs":["(23)"],"by":{"2":"26"}},{"t":"reg","label":"ADMINISTRATIVE MATERIALS Definition of Compensation for Purposes of the Railroad Retirement Tax Act, 44 Fed. Reg. 15,484","url":"https://www.govinfo.gov/link/fr/44/15484","by":{"2":"53"}},{"t":"reg","label":"Republication of Regulations, 25 Fed. Reg. 13,032","url":"https://www.govinfo.gov/link/fr/25/13032","by":{"2":"52-53"}},{"t":"case","label":"Auer v. Robbins","cite":"519 U.S. 452","y":1997,"id":"1996/95-897","sc":1,"sum":"Authored by Justice Antonin Scalia, the Court ruled that sergeants and lieutenants are exempt as salaried employees from the federal Fair Labor Standards Act. The justices rejected the argument that the possibility of suspension without pay moves the officers out of the exempt category.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Barnhart v. Walton","cite":"535 U.S. 212","y":2002,"id":"2001/00-1937","sc":1,"sum":"The Court held that the Social Security Administration's interpretations of the statute fell within its lawful interpretative authority.","sumSrc":"Oyez","by":{"3":"24"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"Envtl. Def. v. Duke Energy Corp.","cite":"549 U.S. 561","y":2007,"id":"2006/05-848","sc":1,"sum":"Unanswered and No. In a unanimous opinion by Justice David Souter, the Court ruled that the EPA need not interpret \"modification\" in PSD regulations the same way the term is interpreted in NSPS regulations. The Court's opinion acknowledged that two occurrences of the same term - sharing the same definition - are normally given the same meaning.","sumSrc":"Oyez","by":{"3":"23"}},{"t":"case","label":"Epsilon Elecs., Inc. v. U.S. Dep’t of Treasury, Ofﬁce of Foreign Assets Control","cite":"857 F.3d 913","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/857/913/","by":{"3":"9"}},{"t":"case","label":"Hawaiian Airlines, Inc. v. Norris","cite":"512 U.S. 246","y":1994,"id":"1993/92-2058","sc":1,"sum":"The RLA does not pre-empt Norris' state-law causes of action.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"10"}},{"t":"case","label":"Kelley v. S. Pac. Co.","cite":"419 U.S. 318","y":1974,"id":"1974/73-1270","sc":1,"sum":"Petitioner, an employee of a trucking company (PMT), was injured while transferring automobiles in respondent's railyard from respondent's railroad car to a PMT auto trailer, an operation that PMT performed under contract for respondent. Although respondent's employees occasionally consulted with PMT employees about the operation, PMT supervisors controlled the day-to-day unloading process. Petitioner, claiming that …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"3"}},{"t":"case","label":"Lifetime Siding, Inc. v. United States","cite":"359 F.2d 657","y":1966,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/359/657/","by":{"3":"7"}},{"t":"case","label":"McNally v. United States","cite":"483 U.S. 350","y":1987,"id":"1986/86-234","sc":1,"sum":"The jury charge permitted a conviction for conduct not within the reach of § 1341.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"10"}},{"t":"case","label":"Mead Corp. v. Tilley","cite":"490 U.S. 714","y":1989,"id":"1988/87-1868","sc":1,"sum":"Under the Employee Retirement Income Security Act of 1974 (ERISA), the Pension Benefit Guaranty Corporation (PBGC) guarantees certain nonforfeitable benefits provided by qualified defined benefit pension plans. When an employer voluntarily terminates a single-employer defined benefit plan, all accrued benefits automatically vest, notwithstanding the plan's particular vesting provisions. Plan assets are then …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"11"}},{"t":"case","label":"Munoz v. Norfolk S. Ry. Co.","cite":"2018 WL 2728696","y":2018,"court":"Ill. App. Ct. June 5","by":{"3":"15"}},{"t":"case","label":"Overstreet v. N. Shore Corp.","cite":"318 U.S. 125","y":1943,"id":"scdb/1942-114","sc":1,"sum":"1. The Fair Labor Standards Act is applicable to employees who are engaged in interstate commerce, but not to those whose activities merely affect interstate commerce.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"11"}},{"t":"case","label":"Schreiber v. Burlington N., Inc.","cite":"472 U.S. 1","y":1985,"id":"1984/83-2129","sc":1,"sum":"In December 1982, respondent Burlington Northern, Inc., made a hostile tender offer for El Paso Gas Co. to which a majority of El Paso's shareholders ultimately subscribed. Burlington did not accept the tendered shares, and instead, in January 1983, after negotiations with El Paso, announced a new and friendly takeover agreement. Pursuant to this agreement, Burlington undertook to rescind the December tender offer …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"10"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"3":"24"}},{"t":"usc","label":"45 U.S.C. § 55","url":"https://www.law.cornell.edu/uscode/text/45/55","by":{"3":"3"}},{"t":"reg","label":"26 C.F.R. § 31.3121","url":"https://www.ecfr.gov/current/title-26/section-31.3121","subs":["(d)"],"by":{"3":"7"}}]};